window.__AtlasPayload=window.__AtlasPayload||{};window.__AtlasPayload["eor-frac-opt"]={"pkg":{"id":"eor-frac-opt","sceneId":"e1","methods":["opt"],"title":"水平井分段压裂代理模型构建与多目标参数寻优","version":"1.0.0","updated":"2026-11-01","tabs":{"background":{"label":"专业背景","lede":"非常规页岩与致密油气藏基质渗透率极低，必须依靠**水平井多段多簇体积压裂（SRV）**打碎储层建立人工渗流通道。然而段内多条水力裂缝同步扩展时会引发强烈的**应力阴影效应（Stress Shadowing）**，导致簇间进液极度不均、中间簇受抑闭合甚至砂堵停泵；而全物理三维流固耦合模拟器单方案耗时数小时，根本无法在数万种「簇间距—排量—液量—砂量」组合中全局寻优。引入**深度学习/高斯过程代理模型**结合**多目标演化寻优（NSGA-II / 贝叶斯优化）**，可将单方案评估压缩至毫秒级，实现「一段一策」的产能与经济净现值（NPV）帕累托全局寻优。","judge":[{"label":"核心优化变量","value":"簇间距 / 排量 / 液砂强度","desc":"单段 4 维核心工程参数 + 3 维地质甜点剖面（最小主应力 σh、脆性指数 BI、天然裂缝密度）联合输入"},{"label":"代理模型加速比","value":"10⁴× 毫秒级推理","desc":"单方案评估由全物理有限元模拟的 3.5 小时降至 1.2 毫秒，支撑万次级全局演化搜索"},{"label":"多目标寻优收益","value":"EUR +18.4% / NPV +24%","desc":"在严控砂堵与隔层穿层风险边界下，同步最大化首年累产（EUR）并降低无效泵注成本"},{"label":"落地难易与条件","value":"中 · 需 150+ 段历史样本","html":"<div style=\"display:flex;align-items:center;gap:8px\"><b>中 · 混合样本驱动</b><svg width=\"54\" height=\"14\" viewBox=\"0 0 54 14\"><rect x=\"1\" y=\"3\" width=\"15\" height=\"8\" rx=\"2\" fill=\"#c27a2c\"/><rect x=\"19\" y=\"3\" width=\"15\" height=\"8\" rx=\"2\" fill=\"#c27a2c\"/><rect x=\"37\" y=\"3\" width=\"15\" height=\"8\" rx=\"2\" fill=\"#e7e3da\"/></svg></div>","desc":"依托区块录井测井、微地震 SRV 与数模拉丁超立方（LHS）合成样本即可快速训练投用"}],"sections":[{"no":1,"en":"","title":"当前做法与问题","html":"<p>在页岩油气与致密砂岩开发中，水平井通常长达 1500–3000 米，被桥塞分割为 25–45 个压裂段，每段内通过射孔枪打出 4–8 簇射孔眼，以高达 12–18 m³/min 的排量泵注数万方滑溜水与石英砂支撑剂，撑开复杂的<b>改造储层体积（SRV, Stimulated Reservoir Volume）</b>。然而现场压裂设计长期面临两大物理与工程困局：</p><p>第一是<b>簇间应力阴影干扰与穿层风险</b>。当段内多簇裂缝同时张开时，外侧裂缝壁面膨胀会对周围岩石产生强烈的附加挤压应力（即<b>应力阴影效应 Stress Shadowing</b>）。若簇间距过密（如 <i>d</i><sub>c</sub> &lt; 8 m），中间射孔簇处的最小水平主应力 <i>σ</i><sub>h</sub> 被急剧抬升，导致压裂液难以进入中间簇——<b>外侧两簇抢液疯长、中间簇发育停滞甚至诱发早期砂堵（Screenout）</b>；反之若排量与用液强度过大，裂缝净压力突破上下泥岩隔层应力差 Δ<i>σ</i>，又会<b>纵向穿层沟通底水或顶水</b>，造成压后含水暴涨。</p><div class=\"figure\"><svg viewBox=\"0 0 760 310\" width=\"100%\" role=\"img\" aria-label=\"水平井多段多簇体积压裂与应力阴影效应机理图\"><defs><linearGradient id=\"efo-shale\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0%\" stop-color=\"#d9d2c5\"/><stop offset=\"18%\" stop-color=\"#e9e2d2\"/><stop offset=\"82%\" stop-color=\"#e5decb\"/><stop offset=\"100%\" stop-color=\"#cbd2d6\"/></linearGradient><radialGradient id=\"efo-srv-good\" cx=\"50%\" cy=\"50%\" r=\"50%\"><stop offset=\"0%\" stop-color=\"#12615a\" stop-opacity=\"0.28\"/><stop offset=\"70%\" stop-color=\"#12615a\" stop-opacity=\"0.10\"/><stop offset=\"100%\" stop-color=\"#12615a\" stop-opacity=\"0\"/></radialGradient><radialGradient id=\"efo-shadow-bad\" cx=\"50%\" cy=\"50%\" r=\"50%\"><stop offset=\"0%\" stop-color=\"#b4483c\" stop-opacity=\"0.34\"/><stop offset=\"65%\" stop-color=\"#c27a2c\" stop-opacity=\"0.14\"/><stop offset=\"100%\" stop-color=\"#c27a2c\" stop-opacity=\"0\"/></radialGradient><marker id=\"efo-arr-red\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,1 L9,5 L0,9 z\" fill=\"#b4483c\"/></marker><marker id=\"efo-arr-teal\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,1 L9,5 L0,9 z\" fill=\"#12615a\"/></marker></defs><rect x=\"0\" y=\"0\" width=\"760\" height=\"310\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><rect x=\"18\" y=\"36\" width=\"350\" height=\"254\" rx=\"6\" fill=\"url(#efo-shale)\" stroke=\"#d9d4c8\"/><rect x=\"18\" y=\"36\" width=\"350\" height=\"38\" fill=\"#c8c2b4\" opacity=\"0.7\"/><rect x=\"18\" y=\"248\" width=\"350\" height=\"42\" fill=\"#b9c7d4\" opacity=\"0.75\"/><line x1=\"18\" y1=\"74\" x2=\"368\" y2=\"74\" stroke=\"#8c7a6b\" stroke-dasharray=\"5,3\"/><line x1=\"18\" y1=\"248\" x2=\"368\" y2=\"248\" stroke=\"#3a6ea5\" stroke-dasharray=\"5,3\"/><text x=\"26\" y=\"24\" font-size=\"12\" font-weight=\"700\" fill=\"#b4483c\">A. 经验过密布簇 + 盲目大排量（应力阴影抑制与隔层穿层）</text><text x=\"26\" y=\"58\" font-size=\"10.5\" fill=\"#424a50\">上部泥岩隔层（高应力遮挡层 σh=62 MPa）</text><text x=\"26\" y=\"268\" font-size=\"10.5\" fill=\"#234b73\">下部含水层 / 底水风险带（一旦穿层含水率飙升）</text><ellipse cx=\"192\" cy=\"160\" rx=\"102\" ry=\"64\" fill=\"url(#efo-shadow-bad)\"/><rect x=\"24\" y=\"155\" width=\"336\" height=\"10\" rx=\"4\" fill=\"#424a50\"/><rect x=\"62\" y=\"151\" width=\"10\" height=\"18\" rx=\"2\" fill=\"#15191c\"/><rect x=\"312\" y=\"151\" width=\"10\" height=\"18\" rx=\"2\" fill=\"#15191c\"/><text x=\"52\" y=\"145\" font-size=\"9.5\" fill=\"#15191c\">桥塞</text><text x=\"304\" y=\"145\" font-size=\"9.5\" fill=\"#15191c\">桥塞</text><path d=\"M112,160 C106,105 109,52 114,42 C118,52 120,105 114,160 C119,210 117,262 112,282 C108,262 107,210 112,160 Z\" fill=\"#b4483c\" opacity=\"0.82\"/><path d=\"M272,160 C266,105 269,52 274,42 C278,52 280,105 274,160 C279,210 277,264 272,284 C268,264 267,210 272,160 Z\" fill=\"#b4483c\" opacity=\"0.82\"/><path d=\"M152,160 C150,136 151,122 153,118 C155,122 156,136 154,160 C155,180 154,195 152,200 C150,195 150,180 152,160 Z\" fill=\"#c27a2c\"/><path d=\"M192,160 C191,146 191,138 192,135 C193,138 193,146 192,160 C193,172 193,180 192,184 C191,180 191,172 192,160 Z\" fill=\"#c27a2c\"/><path d=\"M232,160 C230,138 231,124 233,120 C235,124 236,138 234,160 C235,180 234,194 232,198 C230,194 230,180 232,160 Z\" fill=\"#c27a2c\"/><line x1=\"120\" y1=\"112\" x2=\"146\" y2=\"112\" stroke=\"#b4483c\" stroke-width=\"1.6\" marker-end=\"url(#efo-arr-red)\"/><line x1=\"264\" y1=\"112\" x2=\"238\" y2=\"112\" stroke=\"#b4483c\" stroke-width=\"1.6\" marker-end=\"url(#efo-arr-red)\"/><line x1=\"160\" y1=\"142\" x2=\"184\" y2=\"142\" stroke=\"#b4483c\" stroke-width=\"1.6\" marker-end=\"url(#efo-arr-red)\"/><line x1=\"224\" y1=\"142\" x2=\"200\" y2=\"142\" stroke=\"#b4483c\" stroke-width=\"1.6\" marker-end=\"url(#efo-arr-red)\"/><rect x=\"134\" y=\"84\" width=\"118\" height=\"22\" rx=\"4\" fill=\"#fff5f3\" stroke=\"#b4483c\"/><text x=\"193\" y=\"99\" font-size=\"10\" font-weight=\"600\" fill=\"#b4483c\" text-anchor=\"middle\">附加挤压应力 Δσs &gt; +6 MPa</text><text x=\"193\" y=\"218\" font-size=\"10\" font-weight=\"600\" fill=\"#8a3026\" text-anchor=\"middle\">中间 3 簇受抑短窄（进液 &lt;12% · 极易砂堵）</text><circle cx=\"113\" cy=\"276\" r=\"6\" fill=\"none\" stroke=\"#b4483c\" stroke-width=\"2\"><animate attributeName=\"r\" values=\"4;9;4\" dur=\"1.8s\" repeatCount=\"indefinite\"/></circle><text x=\"124\" y=\"280\" font-size=\"9.5\" font-weight=\"700\" fill=\"#b4483c\">外侧簇纵向穿层出水！</text><rect x=\"392\" y=\"36\" width=\"350\" height=\"254\" rx=\"6\" fill=\"url(#efo-shale)\" stroke=\"#d9d4c8\"/><rect x=\"392\" y=\"36\" width=\"350\" height=\"38\" fill=\"#c8c2b4\" opacity=\"0.7\"/><rect x=\"392\" y=\"248\" width=\"350\" height=\"42\" fill=\"#b9c7d4\" opacity=\"0.75\"/><line x1=\"392\" y1=\"74\" x2=\"742\" y2=\"74\" stroke=\"#8c7a6b\" stroke-dasharray=\"5,3\"/><line x1=\"392\" y1=\"248\" x2=\"742\" y2=\"248\" stroke=\"#3a6ea5\" stroke-dasharray=\"5,3\"/><text x=\"398\" y=\"24\" font-size=\"12\" font-weight=\"700\" fill=\"#12615a\">B. 智能寻优定制方案（簇间距与排量协同 · 均匀充分改造 SRV）</text><ellipse cx=\"466\" cy=\"160\" rx=\"34\" ry=\"76\" fill=\"url(#efo-srv-good)\" stroke=\"#12615a\" stroke-dasharray=\"3,2\"/><ellipse cx=\"526\" cy=\"160\" rx=\"34\" ry=\"78\" fill=\"url(#efo-srv-good)\" stroke=\"#12615a\" stroke-dasharray=\"3,2\"/><ellipse cx=\"586\" cy=\"160\" rx=\"34\" ry=\"78\" fill=\"url(#efo-srv-good)\" stroke=\"#12615a\" stroke-dasharray=\"3,2\"/><ellipse cx=\"646\" cy=\"160\" rx=\"34\" ry=\"76\" fill=\"url(#efo-srv-good)\" stroke=\"#12615a\" stroke-dasharray=\"3,2\"/><rect x=\"398\" y=\"155\" width=\"336\" height=\"10\" rx=\"4\" fill=\"#424a50\"/><rect x=\"424\" y=\"151\" width=\"10\" height=\"18\" rx=\"2\" fill=\"#15191c\"/><rect x=\"686\" y=\"151\" width=\"10\" height=\"18\" rx=\"2\" fill=\"#15191c\"/><path d=\"M466,160 C462,115 463,92 466,84 C469,92 470,115 466,160 C470,205 469,228 466,236 C463,228 462,205 466,160 Z\" fill=\"#12615a\"/><path d=\"M526,160 C522,112 523,88 526,80 C529,88 530,112 526,160 C530,208 529,232 526,240 C523,232 522,208 526,160 Z\" fill=\"#12615a\"/><path d=\"M586,160 C582,112 583,88 586,80 C589,88 590,112 586,160 C590,208 589,232 586,240 C583,232 582,208 586,160 Z\" fill=\"#12615a\"/><path d=\"M646,160 C642,115 643,92 646,84 C649,92 650,115 646,160 C650,205 649,228 646,236 C643,228 642,205 646,160 Z\" fill=\"#12615a\"/><line x1=\"466\" y1=\"106\" x2=\"526\" y2=\"106\" stroke=\"#12615a\" stroke-width=\"1.4\" marker-end=\"url(#efo-arr-teal)\"/><text x=\"496\" y=\"101\" font-size=\"9.5\" font-weight=\"600\" fill=\"#12615a\" text-anchor=\"middle\">最优 dc=15m</text><line x1=\"708\" y1=\"82\" x2=\"708\" y2=\"238\" stroke=\"#12615a\" stroke-width=\"1.5\"/><text x=\"722\" y=\"158\" font-size=\"9.5\" font-weight=\"600\" fill=\"#12615a\" text-anchor=\"middle\" transform=\"rotate(90 722 158)\">安全缝高 hf (不穿层)</text><rect x=\"452\" y=\"44\" width=\"212\" height=\"22\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\"/><text x=\"558\" y=\"59\" font-size=\"10\" font-weight=\"600\" fill=\"#12615a\" text-anchor=\"middle\">各簇均匀扩展 · 有效 SRV 提升 +36%</text><text x=\"558\" y=\"268\" font-size=\"10\" font-weight=\"600\" fill=\"#12615a\" text-anchor=\"middle\">完整避开底水层 · 支撑剂高导流有效铺置</text></svg></div><div class=\"figcap\"><b>图 1</b><span>非常规水平井段内多簇体积压裂（SRV）与「应力阴影效应」对比：左图簇间距过密导致外侧簇挤压中间簇、进液严重失衡并突破底水隔层；右图经参数寻优后实现各簇均匀扩展与安全控缝高。</span></div><p>第二是<b>传统几何均匀模版与全物理模拟器算力瓶颈的对立</b>。水平井沿程岩石脆性（BI）与地应力差往往剧烈波动，但现场工程师受限于工期，普遍采用「全井一刀切」的邻井几何模版（如全井固定 12 m 簇间距、14 m³/min 排量），导致高应力段改造不足、低应力段过度压裂浪费成本。而若使用全三维流固耦合有限元/离散元模拟器（如 KGD/P3D/DFN），<b>单段单方案模拟就需耗时 2–4 小时</b>，面对 4 个连续参数构成的万级搜索空间，传统数模根本无法完成全局寻优。</p><div class=\"figure\"><svg viewBox=\"0 0 760 220\" width=\"100%\" role=\"img\" aria-label=\"传统经验模版与全物理数模耗时困局对比图\"><rect x=\"0\" y=\"0\" width=\"760\" height=\"220\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><text x=\"24\" y=\"28\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">单段压裂方案寻优（2,000 次参数组合评估）三种技术路线耗时与收益对比</text><g transform=\"translate(24,48)\"><rect x=\"0\" y=\"0\" width=\"712\" height=\"46\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/><text x=\"14\" y=\"20\" font-size=\"11.5\" font-weight=\"700\" fill=\"#737c83\">① 传统邻井几何模版</text><text x=\"14\" y=\"36\" font-size=\"10\" fill=\"#737c83\">全井统一段簇参数，忽略沿程应力差异</text><rect x=\"204\" y=\"13\" width=\"38\" height=\"20\" rx=\"4\" fill=\"#d9d4c8\"/><text x=\"250\" y=\"27\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#424a50\">人工套用 ~0.5 h（仅评估 1–3 组经验值）</text><rect x=\"554\" y=\"11\" width=\"144\" height=\"24\" rx=\"4\" fill=\"#f6e3df\"/><text x=\"626\" y=\"27\" font-size=\"10.5\" font-weight=\"600\" fill=\"#b4483c\" text-anchor=\"middle\">簇间均匀度 0.54 · EUR 偏低</text></g><g transform=\"translate(24,104)\"><rect x=\"0\" y=\"0\" width=\"712\" height=\"46\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/><text x=\"14\" y=\"20\" font-size=\"11.5\" font-weight=\"700\" fill=\"#c27a2c\">② 全物理 3D 数值模拟</text><text x=\"14\" y=\"36\" font-size=\"10\" fill=\"#737c83\">流固耦合 + 离散缝网 DFN 网格求解</text><rect x=\"204\" y=\"13\" width=\"338\" height=\"20\" rx=\"4\" fill=\"#c27a2c\"/><text x=\"212\" y=\"27\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#fff\" font-weight=\"600\">单次 3.5h × 2000次 = 7,000 小时 (约291天，不可行)</text><rect x=\"554\" y=\"11\" width=\"144\" height=\"24\" rx=\"4\" fill=\"#f7ecdd\"/><text x=\"626\" y=\"27\" font-size=\"10.5\" font-weight=\"600\" fill=\"#c27a2c\" text-anchor=\"middle\">精度高但无法全局搜索</text></g><g transform=\"translate(24,160)\"><rect x=\"0\" y=\"0\" width=\"712\" height=\"46\" rx=\"6\" fill=\"#e3efec\" stroke=\"#12615a\" stroke-width=\"1.4\"/><text x=\"14\" y=\"20\" font-size=\"11.5\" font-weight=\"700\" fill=\"#12615a\">③ 代理模型 + 多目标寻优</text><text x=\"14\" y=\"36\" font-size=\"10\" fill=\"#12615a\">LHS 抽样离线训练 + 在线毫秒级帕累托寻优</text><rect x=\"204\" y=\"13\" width=\"8\" height=\"20\" rx=\"2\" fill=\"#12615a\"/><text x=\"220\" y=\"27\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#12615a\" font-weight=\"700\">1.2 ms/次 × 2000 次 = 2.4 秒完成全局寻优（提速 10⁴ 倍）</text><rect x=\"554\" y=\"11\" width=\"144\" height=\"24\" rx=\"4\" fill=\"#12615a\"/><text x=\"626\" y=\"27\" font-size=\"10.5\" font-weight=\"600\" fill=\"#fff\" text-anchor=\"middle\">均匀度 0.89 · EUR +18.4%</text></g></svg></div><div class=\"figcap\"><b>图 2</b><span>三种压裂设计技术路线对比：全物理数模单次耗时数小时无法支撑多参数全局搜索，而代理模型将 2000 次演化寻优压缩至 2.4 秒。</span></div>"},{"no":2,"en":"","title":"AI 能做什么","html":"<p>智能化方法并非直接抛弃物理力学规律，而是构建<b>「物理仿真离线采样 + 深度/高斯过程代理模型（Surrogate Model）+ 多目标演化/贝叶斯在线寻优」</b>的双层闭环架构。首先在离线阶段，利用拉丁超立方采样（LHS）生成数百组覆盖不同地质甜点与施工参数的代表性方案，由高精度流固耦合数模与历史压裂井实测数据标定出「输入参数 → SRV / 簇间均匀度 / EUR / 砂堵概率」的映射样本库。</p><p>随后训练<b>多层感知机（MLP）或高斯过程回归（GPR）代理模型</b>，拟合高维非线性的水力裂缝扩展响应曲面。在线设计时，针对水平井每一段的实测岩石力学参数（最小水平主应力 <i>σ</i><sub>h</sub>、脆性指数 BI、层间应力差 Δ<i>σ</i>），调用 <b>NSGA-II 多目标遗传算法或贝叶斯优化（Bayesian Optimization）</b>在毫秒级代理曲面上迭代搜索数千次，自动避开「砂堵高压禁区」与「隔层穿层边界」，输出兼顾<b>最高累产 EUR 与最优经济净现值 NPV</b> 的帕累托前沿（Pareto Front）定制方案。</p><div class=\"figure\"><svg viewBox=\"0 0 760 280\" width=\"100%\" role=\"img\" aria-label=\"岩石力学剖面与代理模型多目标帕累托寻优闭环图\"><defs><marker id=\"efo-arr-flow\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,1 L9,5 L0,9 z\" fill=\"#12615a\"/></marker><linearGradient id=\"efo-surf-grad\" x1=\"0\" y1=\"1\" x2=\"1\" y2=\"0\"><stop offset=\"0%\" stop-color=\"#e3ecf6\"/><stop offset=\"55%\" stop-color=\"#cbe3dc\"/><stop offset=\"85%\" stop-color=\"#f7ecdd\"/><stop offset=\"100%\" stop-color=\"#f6e3df\"/></linearGradient></defs><rect x=\"0\" y=\"0\" width=\"760\" height=\"280\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><g transform=\"translate(18,22)\"><rect x=\"0\" y=\"0\" width=\"188\" height=\"236\" rx=\"8\" fill=\"#fff\" stroke=\"#d9d4c8\"/><rect x=\"0\" y=\"0\" width=\"188\" height=\"28\" rx=\"8\" fill=\"#f0ede5\"/><text x=\"94\" y=\"18\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">1. 地质甜点 + 工程决策输入</text><text x=\"12\" y=\"48\" font-size=\"10.5\" font-weight=\"700\" fill=\"#3a6ea5\">▸ 地质力学剖面 (不可控状态)</text><text x=\"16\" y=\"66\" font-size=\"10\" fill=\"#424a50\">• 最小主应力 σh (52–64 MPa)</text><text x=\"16\" y=\"82\" font-size=\"10\" fill=\"#424a50\">• 岩石脆性指数 BI (0.35–0.75)</text><text x=\"16\" y=\"98\" font-size=\"10\" fill=\"#424a50\">• 隔层应力差 Δσ &amp; 天然裂缝密度</text><line x1=\"12\" y1=\"112\" x2=\"176\" y2=\"112\" stroke=\"#e7e3da\"/><text x=\"12\" y=\"130\" font-size=\"10.5\" font-weight=\"700\" fill=\"#12615a\">▸ 压裂工程参数 (待寻优变量 x)</text><rect x=\"12\" y=\"140\" width=\"164\" height=\"20\" rx=\"4\" fill=\"#e3efec\"/><text x=\"18\" y=\"154\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#12615a\">簇间距 dc ∈ [6, 24] m</text><rect x=\"12\" y=\"164\" width=\"164\" height=\"20\" rx=\"4\" fill=\"#e3efec\"/><text x=\"18\" y=\"178\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#12615a\">施工排量 Q  ∈ [8, 18] m³/min</text><rect x=\"12\" y=\"188\" width=\"164\" height=\"20\" rx=\"4\" fill=\"#e3efec\"/><text x=\"18\" y=\"202\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#12615a\">加砂强度 Mp ∈ [1.0, 3.8] t/m</text><rect x=\"12\" y=\"212\" width=\"164\" height=\"18\" rx=\"4\" fill=\"#e3efec\"/><text x=\"18\" y=\"225\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#12615a\">用液强度 Vf ∈ [12, 36] m³/m</text></g><line x1=\"206\" y1=\"140\" x2=\"234\" y2=\"140\" stroke=\"#12615a\" stroke-width=\"2\" marker-end=\"url(#efo-arr-flow)\"/><g transform=\"translate(238,22)\"><rect x=\"0\" y=\"0\" width=\"244\" height=\"236\" rx=\"8\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.5\"/><rect x=\"0\" y=\"0\" width=\"244\" height=\"28\" rx=\"8\" fill=\"#e3efec\"/><text x=\"122\" y=\"18\" font-size=\"11.5\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">2. 物理约束代理模型 (MLP / GPR)</text><rect x=\"16\" y=\"38\" width=\"212\" height=\"112\" rx=\"6\" fill=\"url(#efo-surf-grad)\" stroke=\"#d9d4c8\"/><ellipse cx=\"106\" cy=\"98\" rx=\"66\" ry=\"32\" fill=\"none\" stroke=\"#12615a\" stroke-dasharray=\"4,3\"/><ellipse cx=\"106\" cy=\"98\" rx=\"40\" ry=\"19\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.3\"/><ellipse cx=\"106\" cy=\"98\" rx=\"16\" ry=\"8\" fill=\"#12615a\" fill-opacity=\"0.25\" stroke=\"#12615a\" stroke-width=\"1.6\"/><path d=\"M164,38 L228,38 L228,84 Q186,78 164,38 Z\" fill=\"#b4483c\" fill-opacity=\"0.28\"/><text x=\"196\" y=\"54\" font-size=\"9\" font-weight=\"700\" fill=\"#b4483c\" text-anchor=\"middle\">砂堵/穿层禁区</text><circle cx=\"106\" cy=\"98\" r=\"4\" fill=\"#c27a2c\" stroke=\"#fff\" stroke-width=\"1.4\"/><text x=\"106\" y=\"73\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">★ 响应曲面极值</text><text x=\"24\" y=\"143\" font-size=\"9\" fill=\"#424a50\">代理曲面 f(x, σh, BI) · 单次 1.2 ms</text><text x=\"16\" y=\"168\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\">同步预测 4 项关键指标：</text><text x=\"18\" y=\"186\" font-size=\"10\" fill=\"#2f7d5b\">✓ 有效改造体积 SRV &amp; 首年累产 EUR</text><text x=\"18\" y=\"202\" font-size=\"10\" fill=\"#12615a\">✓ 簇间进液均匀度 UI ∈ [0, 1]</text><text x=\"18\" y=\"218\" font-size=\"10\" fill=\"#b4483c\">✓ 施工最高泵压 Pmax &amp; 砂堵风险概率</text></g><line x1=\"482\" y1=\"140\" x2=\"510\" y2=\"140\" stroke=\"#12615a\" stroke-width=\"2\" marker-end=\"url(#efo-arr-flow)\"/><g transform=\"translate(514,22)\"><rect x=\"0\" y=\"0\" width=\"228\" height=\"236\" rx=\"8\" fill=\"#fff\" stroke=\"#d9d4c8\"/><rect x=\"0\" y=\"0\" width=\"228\" height=\"28\" rx=\"8\" fill=\"#f0ede5\"/><text x=\"114\" y=\"18\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">3. NSGA-II 帕累托寻优与定制输出</text><rect x=\"16\" y=\"38\" width=\"196\" height=\"112\" rx=\"6\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><line x1=\"36\" y1=\"134\" x2=\"200\" y2=\"134\" stroke=\"#737c83\"/><line x1=\"36\" y1=\"134\" x2=\"36\" y2=\"48\" stroke=\"#737c83\"/><text x=\"118\" y=\"146\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">单段压裂总成本 (万元) →</text><text x=\"26\" y=\"92\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\" transform=\"rotate(-90 26 92)\">预测 EUR →</text><circle cx=\"75\" cy=\"116\" r=\"3\" fill=\"#a3aab0\"/><circle cx=\"95\" cy=\"108\" r=\"3\" fill=\"#a3aab0\"/><circle cx=\"118\" cy=\"105\" r=\"3\" fill=\"#a3aab0\"/><circle cx=\"142\" cy=\"98\" r=\"3\" fill=\"#a3aab0\"/><circle cx=\"166\" cy=\"92\" r=\"3\" fill=\"#a3aab0\"/><circle cx=\"130\" cy=\"114\" r=\"4\" fill=\"#737c83\"/><text x=\"140\" y=\"122\" font-size=\"8.5\" fill=\"#737c83\">传统均匀点</text><path d=\"M52,118 Q86,68 188,58\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.2\"/><circle cx=\"66\" cy=\"98\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"92\" cy=\"78\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"118\" cy=\"68\" r=\"5.5\" fill=\"#c27a2c\" stroke=\"#fff\" stroke-width=\"1.5\"/><circle cx=\"154\" cy=\"62\" r=\"3.5\" fill=\"#12615a\"/><text x=\"118\" y=\"54\" font-size=\"9\" font-weight=\"700\" fill=\"#c27a2c\" text-anchor=\"middle\">★ 帕累托拐点 (最大 NPV)</text><rect x=\"16\" y=\"160\" width=\"196\" height=\"64\" rx=\"6\" fill=\"#e3efec\" stroke=\"#12615a\"/><text x=\"26\" y=\"178\" font-size=\"10\" font-weight=\"700\" fill=\"#12615a\">输出「一段一策」定制泵注施工表：</text><text x=\"26\" y=\"195\" font-size=\"9.5\" fill=\"#424a50\">• Ⅰ类甜点段：密簇 (12m) + 高砂比扩 SRV</text><text x=\"26\" y=\"211\" font-size=\"9.5\" fill=\"#424a50\">• Ⅲ类高应力段：疏簇 (18m) + 控排防砂堵</text></g><path d=\"M628,258 L628,272 L360,272 L360,258\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><text x=\"494\" y=\"269\" font-size=\"9.5\" font-weight=\"600\" fill=\"#c27a2c\" text-anchor=\"middle\">↻ 压后微地震 SRV 与返排产量回流重标定代理模型权重</text></svg></div><div class=\"figcap\"><b>图 3</b><span>地质—工程一体化的压裂代理模型构建与多目标帕累托寻优闭环：融合岩石力学剖面与毫秒级响应曲面，自动在成本与 EUR 之间锁定最大净现值拐点。</span></div>"},{"no":3,"en":"","title":"需要准备什么","html":"<p>构建高可靠性的压裂参数代理模型，核心在于将<b>随钻测井岩石力学剖面、泵注施工高频时序记录、微地震监测缝网几何与压后生产动态</b>对齐到「单段/单井」粒度，并辅以拉丁超立方采样（LHS）数值模拟结果填补极端参数空白区：</p><div class=\"checklist\"><div class=\"cl-head\"><span>数据准备清单 · 3 项</span><span class=\"cl-prog\"><span id=\"cl-txt\">0 / 3</span><span class=\"cl-bar\"><i id=\"cl-fill\"></i></span></span></div><div class=\"cl-item\" data-cl=\"0\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">水平段测井脆性指数与最小主应力剖面</span><span class=\"cl-s\">不少于 15 口井 / 300+ 压裂段，采样分辨率 0.125 m，含杨氏模量 E、泊松比 ν、最小主应力 σh 及天然裂缝发育密度</span></span><span class=\"cl-n\">按桥塞深度聚合为单段均值与方差</span></div><div class=\"cl-item\" data-cl=\"1\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">分段压裂施工排量砂比曲线与微地震SRV</span><span class=\"cl-s\">每段簇数、簇间距 dc、秒级施工排量 Q、井口泵压 P、加砂强度 Mp、用液强度 Vf，以及至少 30% 段具备微地震监测缝长 xf/缝高 hf/SRV</span></span><span class=\"cl-n\">标注异常砂堵停泵与套变事件标签</span></div><div class=\"cl-item\" data-cl=\"2\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">压后返排测试产量与EUR标定集</span><span class=\"cl-s\">单井首年累产（1-Year EUR）与产剖测试（PLT/光纤分布式声波 DAS）折算的单段贡献率，加 400 组 LHS 数值模拟合成样本</span></span><span class=\"cl-n\">统一折算至标准油气当量与净现值 NPV</span></div></div><div class=\"figure\"><svg viewBox=\"0 0 760 248\" width=\"100%\" role=\"img\" aria-label=\"拉丁超立方采样空间覆盖与代理模型预测误差校准图\"><rect x=\"0\" y=\"0\" width=\"760\" height=\"248\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><g transform=\"translate(22,18)\"><rect x=\"0\" y=\"0\" width=\"342\" height=\"212\" rx=\"8\" fill=\"#fff\" stroke=\"#d9d4c8\"/><text x=\"16\" y=\"21\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">A. 拉丁超立方采样 (LHS) 参数空间正交覆盖</text><text x=\"16\" y=\"36\" font-size=\"9.5\" fill=\"#737c83\">确保每行每列恰有 1 个采样点，弥补现场历史经验数据聚集盲区</text><g transform=\"translate(48,46)\"><rect x=\"0\" y=\"0\" width=\"240\" height=\"120\" fill=\"#fbfaf7\" stroke=\"#737c83\"/><line x1=\"40\" y1=\"0\" x2=\"40\" y2=\"120\" stroke=\"#e7e3da\"/><line x1=\"80\" y1=\"0\" x2=\"80\" y2=\"120\" stroke=\"#e7e3da\"/><line x1=\"120\" y1=\"0\" x2=\"120\" y2=\"120\" stroke=\"#e7e3da\"/><line x1=\"160\" y1=\"0\" x2=\"160\" y2=\"120\" stroke=\"#e7e3da\"/><line x1=\"200\" y1=\"0\" x2=\"200\" y2=\"120\" stroke=\"#e7e3da\"/><line x1=\"0\" y1=\"20\" x2=\"240\" y2=\"20\" stroke=\"#e7e3da\"/><line x1=\"0\" y1=\"40\" x2=\"240\" y2=\"40\" stroke=\"#e7e3da\"/><line x1=\"0\" y1=\"60\" x2=\"240\" y2=\"60\" stroke=\"#e7e3da\"/><line x1=\"0\" y1=\"80\" x2=\"240\" y2=\"80\" stroke=\"#e7e3da\"/><line x1=\"0\" y1=\"100\" x2=\"240\" y2=\"100\" stroke=\"#e7e3da\"/><ellipse cx=\"116\" cy=\"68\" rx=\"42\" ry=\"24\" fill=\"#c27a2c\" fill-opacity=\"0.18\" stroke=\"#c27a2c\" stroke-dasharray=\"3,2\"/><circle cx=\"106\" cy=\"65\" r=\"3\" fill=\"#c27a2c\"/><circle cx=\"122\" cy=\"72\" r=\"3\" fill=\"#c27a2c\"/><circle cx=\"114\" cy=\"58\" r=\"3\" fill=\"#c27a2c\"/><circle cx=\"130\" cy=\"66\" r=\"3\" fill=\"#c27a2c\"/><circle cx=\"22\" cy=\"90\" r=\"4.5\" fill=\"#12615a\"/><circle cx=\"58\" cy=\"30\" r=\"4.5\" fill=\"#12615a\"/><circle cx=\"98\" cy=\"110\" r=\"4.5\" fill=\"#12615a\"/><circle cx=\"142\" cy=\"10\" r=\"4.5\" fill=\"#12615a\"/><circle cx=\"178\" cy=\"70\" r=\"4.5\" fill=\"#12615a\"/><circle cx=\"222\" cy=\"50\" r=\"4.5\" fill=\"#12615a\"/><text x=\"120\" y=\"136\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\">簇间距 dc (6 → 24 m)</text><text x=\"-12\" y=\"60\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\" transform=\"rotate(-90 -12 60)\">施工排量 Q →</text></g><circle cx=\"84\" cy=\"198\" r=\"4\" fill=\"#12615a\"/><text x=\"93\" y=\"201\" font-size=\"9\" fill=\"#424a50\">LHS 数模正交点</text><circle cx=\"196\" cy=\"198\" r=\"3.5\" fill=\"#c27a2c\"/><text x=\"205\" y=\"201\" font-size=\"9\" fill=\"#424a50\">历史经验扎堆区</text></g><g transform=\"translate(388,18)\"><rect x=\"0\" y=\"0\" width=\"350\" height=\"212\" rx=\"8\" fill=\"#fff\" stroke=\"#d9d4c8\"/><text x=\"16\" y=\"21\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">B. 代理模型 EUR 预测值 vs 真值交叉验证校准</text><text x=\"16\" y=\"36\" font-size=\"9.5\" fill=\"#737c83\">5 折交叉验证：测试集决定系数 R² = 0.942，平均相对误差 MAPE = 4.6%</text><g transform=\"translate(52,46)\"><rect x=\"0\" y=\"0\" width=\"264\" height=\"120\" fill=\"#fbfaf7\" stroke=\"#737c83\"/><polygon points=\"0,108 240,0 264,0 264,14 24,120 0,120\" fill=\"#12615a\" fill-opacity=\"0.12\"/><line x1=\"0\" y1=\"120\" x2=\"264\" y2=\"0\" stroke=\"#12615a\" stroke-width=\"1.6\" stroke-dasharray=\"5,3\"/><circle cx=\"34\" cy=\"103\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"58\" cy=\"95\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"82\" cy=\"81\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"108\" cy=\"73\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"126\" cy=\"60\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"152\" cy=\"52\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"176\" cy=\"39\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"198\" cy=\"31\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"224\" cy=\"17\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"70\" cy=\"87\" r=\"3.5\" fill=\"#3a6ea5\"/><circle cx=\"140\" cy=\"57\" r=\"3.5\" fill=\"#3a6ea5\"/><circle cx=\"210\" cy=\"25\" r=\"3.5\" fill=\"#3a6ea5\"/><rect x=\"148\" y=\"80\" width=\"106\" height=\"32\" rx=\"4\" fill=\"#fff\" stroke=\"#12615a\"/><text x=\"201\" y=\"94\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">R² = 0.942</text><text x=\"201\" y=\"107\" font-size=\"9\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#424a50\" text-anchor=\"middle\">±5% 误差带覆盖 93%</text><text x=\"132\" y=\"136\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\">全物理数模 / 实测 EUR 真值 (万m³)</text><text x=\"-12\" y=\"60\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\" transform=\"rotate(-90 -12 60)\">代理预测值 →</text></g><circle cx=\"92\" cy=\"198\" r=\"3.5\" fill=\"#12615a\"/><text x=\"101\" y=\"201\" font-size=\"9\" fill=\"#424a50\">数模验证样本</text><circle cx=\"194\" cy=\"198\" r=\"3.5\" fill=\"#3a6ea5\"/><text x=\"203\" y=\"201\" font-size=\"9\" fill=\"#424a50\">微地震与产剖实测井</text></g></svg></div><div class=\"figcap\"><b>图 4</b><span>拉丁超立方采样（LHS）打破现场历史参数扎堆盲区（左），使代理模型在整个搜索空间内达到 R²=0.942 的高精度校准（右）。</span></div>"},{"no":4,"en":"","title":"难度与参考方向","html":"<p>压裂智能寻优落地最大的工程挑战在于<b>地质不确定性（Geological Uncertainty）与砂堵安全边界的耦合</b>。随钻测井反演的地应力与天然裂缝密度不可避免存在 ±2 MPa 的局部波动；若确定性寻优将方案推至贴近砂堵或套变压力红线的「悬崖边缘（Knife-edge Optimum）」，一旦施工段内遭遇未探明的微断层或高应力夹层，极易诱发<b>早期砂堵停泵或丢段事故</b>。</p><p>因此实际工业部署必须采用<b>鲁棒贝叶斯优化（Robust Bayesian Optimization）</b>：利用高斯过程代理模型输出的预测方差 <i>σ</i>(<b>x</b>)，对高不确定性区域施加风险惩罚，主动向安全裕度内退让 1.5–2.0 m 簇间距，寻找对地质扰动不敏感的「宽平高产平台区（Robust Optimum）」。</p><div class=\"figure\"><svg viewBox=\"0 0 760 235\" width=\"100%\" role=\"img\" aria-label=\"地质不确定性下的鲁棒优化与砂堵风险边界剖析图\"><rect x=\"0\" y=\"0\" width=\"760\" height=\"235\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><g transform=\"translate(22,18)\"><rect x=\"0\" y=\"0\" width=\"424\" height=\"198\" rx=\"8\" fill=\"#fff\" stroke=\"#d9d4c8\"/><text x=\"16\" y=\"22\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">A. 确定性悬崖极值 vs 地质扰动下的鲁棒最优点</text><g transform=\"translate(44,36)\"><rect x=\"0\" y=\"0\" width=\"358\" height=\"132\" fill=\"#fbfaf7\" stroke=\"#737c83\"/><rect x=\"0\" y=\"0\" width=\"74\" height=\"132\" fill=\"#f6e3df\" opacity=\"0.75\"/><line x1=\"74\" y1=\"0\" x2=\"74\" y2=\"132\" stroke=\"#b4483c\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><text x=\"37\" y=\"22\" font-size=\"9.5\" font-weight=\"700\" fill=\"#b4483c\" text-anchor=\"middle\">高压砂堵禁区</text><text x=\"37\" y=\"36\" font-size=\"8.5\" fill=\"#b4483c\" text-anchor=\"middle\">Pmax &gt; 85 MPa</text><path d=\"M28,122 C54,116 68,26 86,24 C106,22 136,52 198,42 C244,36 286,58 342,96 L342,118 C286,82 244,56 198,60 C136,68 106,58 86,68 C68,78 54,126 28,128 Z\" fill=\"#12615a\" fill-opacity=\"0.16\"/><path d=\"M28,125 C54,120 68,38 86,36 C106,34 136,58 198,50 C244,44 286,70 342,106\" fill=\"none\" stroke=\"#737c83\" stroke-width=\"1.6\" stroke-dasharray=\"5,3\"/><path d=\"M28,126 C58,122 96,92 142,62 C174,42 204,40 236,48 C272,58 304,82 342,108\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.4\"/><circle cx=\"86\" cy=\"36\" r=\"4.5\" fill=\"#b4483c\"/><text x=\"82\" y=\"19\" font-size=\"9\" font-weight=\"700\" fill=\"#b4483c\">名义极值 (微扰即跌入砂堵崖)</text><circle cx=\"212\" cy=\"43\" r=\"5.5\" fill=\"#12615a\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"256\" y=\"34\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">★ 鲁棒最优点 (宽平台抗扰)</text><text x=\"179\" y=\"148\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\">簇间距 dc / 砂比安全裕度 →</text><text x=\"-12\" y=\"66\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\" transform=\"rotate(-90 -12 66)\">期望净现值 E[NPV] →</text></g></g><g transform=\"translate(464,18)\"><rect x=\"0\" y=\"0\" width=\"274\" height=\"198\" rx=\"8\" fill=\"#fff\" stroke=\"#d9d4c8\"/><text x=\"16\" y=\"22\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">B. 工程落地四维难度剖析</text><g transform=\"translate(16,40)\"><text x=\"0\" y=\"14\" font-size=\"10\" fill=\"#424a50\">微地震与产剖样本稀缺度</text><rect x=\"128\" y=\"4\" width=\"114\" height=\"10\" rx=\"5\" fill=\"#f0ede5\"/><rect x=\"128\" y=\"4\" width=\"94\" height=\"10\" rx=\"5\" fill=\"#b4483c\"/><text x=\"128\" y=\"27\" font-size=\"8.5\" fill=\"#737c83\">需迁移学习 + LHS 数模融合扩充</text><text x=\"0\" y=\"52\" font-size=\"10\" fill=\"#424a50\">天然裂缝与套变风险表征</text><rect x=\"128\" y=\"42\" width=\"114\" height=\"10\" rx=\"5\" fill=\"#f0ede5\"/><rect x=\"128\" y=\"42\" width=\"86\" height=\"10\" rx=\"5\" fill=\"#c27a2c\"/><text x=\"128\" y=\"65\" font-size=\"8.5\" fill=\"#737c83\">走滑断层带易诱发套管变形丢段</text><text x=\"0\" y=\"90\" font-size=\"10\" fill=\"#424a50\">物理力学守恒一致性约束</text><rect x=\"128\" y=\"80\" width=\"114\" height=\"10\" rx=\"5\" fill=\"#f0ede5\"/><rect x=\"128\" y=\"80\" width=\"68\" height=\"10\" rx=\"5\" fill=\"#3a6ea5\"/><text x=\"128\" y=\"103\" font-size=\"8.5\" fill=\"#737c83\">引入物质平衡与单调性正则项</text><text x=\"0\" y=\"128\" font-size=\"10\" fill=\"#424a50\">现场泵车离散档位可执行性</text><rect x=\"128\" y=\"118\" width=\"114\" height=\"10\" rx=\"5\" fill=\"#f0ede5\"/><rect x=\"128\" y=\"118\" width=\"42\" height=\"10\" rx=\"5\" fill=\"#2f7d5b\"/><text x=\"128\" y=\"141\" font-size=\"8.5\" fill=\"#737c83\">连续最优解需量化为标准泵注程序表</text></g></g></svg></div><div class=\"figcap\"><b>图 5</b><span>考虑地应力测量不确定性的鲁棒优化（左）：避开紧邻砂堵红线的「名义尖峰」，选择对天然裂缝与应力波动具有强抗扰能力的宽平高产区。</span></div><div class=\"callout\"><span class=\"ci\">延伸方向</span><span>可进一步结合压裂施工实时井口泵压反演（净压力拟合 Net Pressure Matching），在泵注过程中动态微调暂堵球投送时机与阶梯砂比。</span></div><div class=\"refs\"><a class=\"ref\" href=\"#/method/opt\">高斯过程代理模型 (GPR)<span class=\"ar\">↗</span></a><a class=\"ref\" href=\"#/method/opt\">NSGA-II 多目标帕累托寻优<span class=\"ar\">↗</span></a><a class=\"ref\" href=\"#/method/opt\">拉丁超立方采样 (LHS)<span class=\"ar\">↗</span></a><a class=\"ref\" href=\"#/method/ts\">施工泵压时序诊断<span class=\"ar\">↗</span></a></div>"}]},"workflow":{"label":"案例流程","title":"分段压裂代理模型构建与多目标参数寻优五步闭环","lead":["围绕水平井「地质甜点非均质性显著、簇间应力阴影抑制严重、三维流固耦合模拟耗时过长」三大核心痛点，将分段压裂优化拆解为从岩石力学表征、LHS 代理建模、安全边界约束到 NSGA-II 帕累托寻优的 5 个标准工程步骤。"],"stats":[["样本库规模","400 组 LHS 数模 + 180 段实测"],["单段寻优耗时","2.4 秒 / 2000 次代理迭代"],["现场验证收益","EUR +18.4% · 簇均匀度 0.89"]],"steps":[{"name":"水平段地质甜点与应力剖面表征","role":"数据","do":"读取随钻声波、密度与伽马测井曲线，计算沿程动态杨氏模量 E、泊松比 ν、岩石脆性指数 BI 以及最小水平主应力 σh 剖面，按地质力学非均质性将水平段聚类为 Ⅰ类高脆甜点段、Ⅱ类致密均质段与 Ⅲ类高应力差隔夹层段。","effect":"精确定位沿程应力障与脆性甜点边界，段内应力标准差控制在 ≤ 1.2 MPa，避免跨岩性突变盲目布簇。","trap":"严禁直接用静态岩心实验值替代连续测井剖面而不做动静态转换标定，否则最小主应力系统偏差可达 4–6 MPa。"},{"name":"拉丁超立方采样与代理模型训练","role":"模型","do":"在 [簇间距 dc, 排量 Q, 加砂强度 Mp, 用液强度 Vf] 四维空间执行拉丁超立方正交采样（LHS），运行三维流固耦合裂缝扩展模拟并融合历史微地震实测样本，训练物理约束多层感知机（MLP）/ 高斯过程（GPR）多输出代理模型。","effect":"测试集 SRV 与 EUR 预测决定系数 R² ≥ 0.94，平均相对误差 MAPE < 5%，单方案推理耗时从 3.5 小时降至 1.2 毫秒。","trap":"若仅用现场历史施工记录训练而不补充 LHS 边界正交样本，代理模型在常规经验区外推时会出现违背物理规律的负缝宽或发散。"},{"name":"施工压力限值与砂堵安全约束设定","role":"质控","do":"基于井口套管抗内压强度（≤ 85 MPa）、地面泵车额定功率及上下隔层应力差 Δσ，在代理模型响应空间内划定「高砂比低排量砂堵禁区」与「大排量隔层穿层边界」，计算簇间进液均匀度硬约束 UI ≥ 0.72。","effect":"提前剔除约 28% 存在早期砂堵停泵或纵向穿底水风险的激进参数组合，现场砂堵率由 9.5% 降至 < 1.2%。","trap":"忽略天然裂缝带的滤失附加压降会导致高估高砂比安全性，必须在微断层发育段收紧最大砂比上限。"},{"name":"多目标帕累托前沿搜索（EUR vs 成本）","role":"算法","do":"以「最大化首年累产 EUR 与簇间均匀度 UI」及「最小化单段压裂液砂与泵注总成本 Cost」为双目标，运行 NSGA-II 演化算法与贝叶斯期望改进准则（EI），求解帕累托最优前沿并按油气价格锁定最大净现值（NPV）拐点方案。","effect":"在 2.4 秒内完成 2000 个候选方案全局寻优，相比传统几何均匀方案单段 NPV 平均提升 24.2%，吨砂产出效率提升 19%。","trap":"单目标只追最高 EUR 会导致边际用液与加砂量无节制膨胀，必须采用含成本折现的 NPV 或帕累托曲率拐点（Knee Point）准则。"},{"name":"差异化段簇方案输出与微地震验证","role":"应用","do":"将各段帕累托最优解转化为现场可执行的射孔簇位置表与阶梯排量—砂比泵注程序表；压中及压后采集微地震事件云（SRV）与光纤产剖（DAS/DTS）数据，回流更新代理模型高斯先验。","effect":"实现全井「一段一策」差异化压裂，簇间开启率由 64% 提升至 91%，压后实测累产与代理模型预测偏差 ≤ 6.2%。","trap":"理论最优簇间距若刚好落在套管接箍（Collar）位置无法射孔，需在输出前做 ±0.8 m 接箍避让工程修正。"}],"metrics":{"title":"流程分镜与验收指标","html":"<div class=\"figure\"><svg viewBox=\"0 0 760 250\" width=\"100%\" role=\"img\" aria-label=\"分段压裂智能寻优五步流程分镜图\"><defs><linearGradient id=\"efo-sb-surf\" x1=\"0\" y1=\"1\" x2=\"1\" y2=\"0\"><stop offset=\"0%\" stop-color=\"#e3ecf6\"/><stop offset=\"55%\" stop-color=\"#b8ddd4\"/><stop offset=\"100%\" stop-color=\"#f7ecdd\"/></linearGradient></defs><rect x=\"0\" y=\"0\" width=\"760\" height=\"250\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><g transform=\"translate(12,14)\"><rect x=\"0\" y=\"0\" width=\"138\" height=\"222\" rx=\"7\" fill=\"#fff\" stroke=\"#d9d4c8\"/><rect x=\"0\" y=\"0\" width=\"138\" height=\"26\" rx=\"7\" fill=\"#f0ede5\"/><text x=\"10\" y=\"17\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\">01</text><text x=\"30\" y=\"17\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\">地质应力表征</text><rect x=\"10\" y=\"36\" width=\"118\" height=\"118\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><path d=\"M16,66 L42,58 L68,78 L96,52 L122,82\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.8\"/><path d=\"M16,118 L42,126 L68,104 L96,130 L122,98\" fill=\"none\" stroke=\"#b4483c\" stroke-width=\"1.8\"/><rect x=\"16\" y=\"138\" width=\"34\" height=\"10\" rx=\"2\" fill=\"#2f7d5b\" opacity=\"0.8\"/><rect x=\"52\" y=\"138\" width=\"36\" height=\"10\" rx=\"2\" fill=\"#3a6ea5\" opacity=\"0.8\"/><rect x=\"90\" y=\"138\" width=\"32\" height=\"10\" rx=\"2\" fill=\"#c27a2c\" opacity=\"0.8\"/><text x=\"20\" y=\"50\" font-size=\"8.5\" fill=\"#12615a\">脆性 BI 曲线</text><text x=\"20\" y=\"100\" font-size=\"8.5\" fill=\"#b4483c\">最小主应力 σh</text><text x=\"69\" y=\"172\" font-size=\"9.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">输入测井岩石力学</text><text x=\"69\" y=\"188\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">划分 Ⅰ/Ⅱ/Ⅲ 类地质段</text><text x=\"69\" y=\"204\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\">σh 误差 ≤ 1.2 MPa</text></g><g transform=\"translate(161,14)\"><rect x=\"0\" y=\"0\" width=\"138\" height=\"222\" rx=\"7\" fill=\"#fff\" stroke=\"#d9d4c8\"/><rect x=\"0\" y=\"0\" width=\"138\" height=\"26\" rx=\"7\" fill=\"#f0ede5\"/><text x=\"10\" y=\"17\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\">02</text><text x=\"30\" y=\"17\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\">LHS 与代理曲面</text><rect x=\"10\" y=\"36\" width=\"118\" height=\"118\" rx=\"4\" fill=\"url(#efo-sb-surf)\" stroke=\"#e7e3da\"/><ellipse cx=\"69\" cy=\"95\" rx=\"46\" ry=\"34\" fill=\"none\" stroke=\"#12615a\" stroke-dasharray=\"3,2\"/><ellipse cx=\"69\" cy=\"95\" rx=\"28\" ry=\"19\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.3\"/><ellipse cx=\"69\" cy=\"95\" rx=\"11\" ry=\"7\" fill=\"#12615a\" fill-opacity=\"0.3\" stroke=\"#12615a\"/><circle cx=\"34\" cy=\"62\" r=\"2.5\" fill=\"#424a50\"/><circle cx=\"98\" cy=\"58\" r=\"2.5\" fill=\"#424a50\"/><circle cx=\"46\" cy=\"126\" r=\"2.5\" fill=\"#424a50\"/><circle cx=\"106\" cy=\"118\" r=\"2.5\" fill=\"#424a50\"/><circle cx=\"69\" cy=\"95\" r=\"3\" fill=\"#c27a2c\"/><text x=\"69\" y=\"172\" font-size=\"9.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">拟合 MLP/GPR 响应面</text><text x=\"69\" y=\"188\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">dc × Q → SRV / EUR</text><text x=\"69\" y=\"204\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\">推理耗时 1.2 ms</text></g><g transform=\"translate(310,14)\"><rect x=\"0\" y=\"0\" width=\"138\" height=\"222\" rx=\"7\" fill=\"#fff\" stroke=\"#d9d4c8\"/><rect x=\"0\" y=\"0\" width=\"138\" height=\"26\" rx=\"7\" fill=\"#f0ede5\"/><text x=\"10\" y=\"17\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\">03</text><text x=\"30\" y=\"17\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\">安全边界裁切</text><rect x=\"10\" y=\"36\" width=\"118\" height=\"118\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><path d=\"M10,36 L68,36 Q52,82 10,94 Z\" fill=\"#b4483c\" fill-opacity=\"0.28\"/><path d=\"M76,36 L128,36 L128,88 Q96,74 76,36 Z\" fill=\"#c27a2c\" fill-opacity=\"0.28\"/><rect x=\"28\" y=\"78\" width=\"76\" height=\"58\" rx=\"6\" fill=\"#e3efec\" stroke=\"#12615a\" stroke-width=\"1.5\"/><text x=\"34\" y=\"54\" font-size=\"8\" font-weight=\"700\" fill=\"#b4483c\">砂堵区</text><text x=\"94\" y=\"54\" font-size=\"8\" font-weight=\"700\" fill=\"#c27a2c\">穿层区</text><text x=\"66\" y=\"110\" font-size=\"9\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">安全可行域 Ω</text><text x=\"69\" y=\"172\" font-size=\"9.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">剔除砂堵与穿层禁区</text><text x=\"69\" y=\"188\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">Pmax ≤ 85MPa · UI ≥ 0.72</text><text x=\"69\" y=\"204\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\">砂堵率降至 &lt;1.2%</text></g><g transform=\"translate(459,14)\"><rect x=\"0\" y=\"0\" width=\"138\" height=\"222\" rx=\"7\" fill=\"#fff\" stroke=\"#d9d4c8\"/><rect x=\"0\" y=\"0\" width=\"138\" height=\"26\" rx=\"7\" fill=\"#f0ede5\"/><text x=\"10\" y=\"17\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\">04</text><text x=\"30\" y=\"17\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\">帕累托前沿搜索</text><rect x=\"10\" y=\"36\" width=\"118\" height=\"118\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><line x1=\"24\" y1=\"138\" x2=\"118\" y2=\"138\" stroke=\"#737c83\"/><line x1=\"24\" y1=\"138\" x2=\"24\" y2=\"48\" stroke=\"#737c83\"/><circle cx=\"48\" cy=\"122\" r=\"2.5\" fill=\"#a3aab0\"/><circle cx=\"68\" cy=\"112\" r=\"2.5\" fill=\"#a3aab0\"/><circle cx=\"88\" cy=\"104\" r=\"2.5\" fill=\"#a3aab0\"/><path d=\"M32,126 Q56,68 112,56\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2\"/><circle cx=\"66\" cy=\"74\" r=\"5\" fill=\"#c27a2c\" stroke=\"#fff\" stroke-width=\"1.2\"/><text x=\"74\" y=\"68\" font-size=\"8.5\" font-weight=\"700\" fill=\"#c27a2c\">★ Knee点</text><text x=\"72\" y=\"149\" font-size=\"8\" fill=\"#737c83\" text-anchor=\"middle\">成本 Cost →</text><text x=\"69\" y=\"172\" font-size=\"9.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">NSGA-II 双目标寻优</text><text x=\"69\" y=\"188\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">平衡高 EUR 与压裂成本</text><text x=\"69\" y=\"204\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\">单段 NPV +24.2%</text></g><g transform=\"translate(608,14)\"><rect x=\"0\" y=\"0\" width=\"140\" height=\"222\" rx=\"7\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.4\"/><rect x=\"0\" y=\"0\" width=\"140\" height=\"26\" rx=\"7\" fill=\"#e3efec\"/><text x=\"10\" y=\"17\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\">05</text><text x=\"30\" y=\"17\" font-size=\"10.5\" font-weight=\"700\" fill=\"#12615a\">差异化方案验证</text><rect x=\"10\" y=\"36\" width=\"120\" height=\"118\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><text x=\"18\" y=\"52\" font-size=\"8\" fill=\"#737c83\">传统均匀布簇 (全段一致)</text><line x1=\"18\" y1=\"62\" x2=\"122\" y2=\"62\" stroke=\"#737c83\" stroke-width=\"3\"/><circle cx=\"30\" cy=\"62\" r=\"3\" fill=\"#737c83\"/><circle cx=\"54\" cy=\"62\" r=\"3\" fill=\"#737c83\"/><circle cx=\"78\" cy=\"62\" r=\"3\" fill=\"#737c83\"/><circle cx=\"102\" cy=\"62\" r=\"3\" fill=\"#737c83\"/><text x=\"18\" y=\"92\" font-size=\"8\" font-weight=\"700\" fill=\"#12615a\">AI 差异化定制 (一段一策)</text><line x1=\"18\" y1=\"104\" x2=\"122\" y2=\"104\" stroke=\"#12615a\" stroke-width=\"3\"/><circle cx=\"26\" cy=\"104\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"42\" cy=\"104\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"58\" cy=\"104\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"86\" cy=\"104\" r=\"3.5\" fill=\"#c27a2c\"/><circle cx=\"114\" cy=\"104\" r=\"3.5\" fill=\"#c27a2c\"/><rect x=\"22\" y=\"120\" width=\"96\" height=\"22\" rx=\"3\" fill=\"#e3efec\"/><text x=\"70\" y=\"134\" font-size=\"8.5\" font-weight=\"600\" fill=\"#12615a\" text-anchor=\"middle\">微地震 SRV 吻合度 94%</text><text x=\"70\" y=\"172\" font-size=\"9.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">输出泵注表与微地震核验</text><text x=\"70\" y=\"188\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">甜点加密 · 隔夹层疏簇</text><text x=\"70\" y=\"204\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\">簇开启率达 91%</text></g></svg></div><div class=\"figcap\"><b>图 6</b><span>五步压裂智能寻优流程分镜：从随钻测井地质甜点表征（01）、LHS 代理曲面拟合（02）、砂堵穿层边界裁切（03）到帕累托寻优（04）与差异化段簇落地（05）。</span></div><div class=\"figure\"><svg viewBox=\"0 0 760 215\" width=\"100%\" role=\"img\" aria-label=\"代理模型拟合精度与现场增产效益验收指标图\"><rect x=\"0\" y=\"0\" width=\"760\" height=\"215\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/><g transform=\"translate(18,18)\"><rect x=\"0\" y=\"0\" width=\"232\" height=\"178\" rx=\"8\" fill=\"#fff\" stroke=\"#d9d4c8\"/><text x=\"14\" y=\"22\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">验收一：代理模型预测精度</text><text x=\"14\" y=\"38\" font-size=\"9.5\" fill=\"#737c83\">对比 3D 模拟器与实测 EUR 误差分布</text><rect x=\"18\" y=\"52\" width=\"196\" height=\"32\" rx=\"5\" fill=\"#e3efec\"/><text x=\"28\" y=\"72\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\">决定系数 R² = 0.942</text><text x=\"152\" y=\"72\" font-size=\"9.5\" fill=\"#2f7d5b\">(达标 ≥0.90)</text><rect x=\"18\" y=\"92\" width=\"196\" height=\"32\" rx=\"5\" fill=\"#f0ede5\"/><text x=\"28\" y=\"112\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">相对误差 MAPE = 4.6%</text><text x=\"154\" y=\"112\" font-size=\"9.5\" fill=\"#2f7d5b\">(达标 &lt;6%)</text><text x=\"18\" y=\"148\" font-size=\"9.5\" fill=\"#424a50\">• 砂堵风险分类召回率：96.4%</text><text x=\"18\" y=\"164\" font-size=\"9.5\" fill=\"#424a50\">• 单段 2000 次寻优总耗时：2.4 s</text></g><g transform=\"translate(264,18)\"><rect x=\"0\" y=\"0\" width=\"232\" height=\"178\" rx=\"8\" fill=\"#fff\" stroke=\"#d9d4c8\"/><text x=\"14\" y=\"22\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">验收二：三类地质段 EUR 增幅</text><text x=\"14\" y=\"38\" font-size=\"9.5\" fill=\"#737c83\">定制寻优方案 vs 传统均匀方案 (+14%~22%)</text><g transform=\"translate(18,52)\"><text x=\"0\" y=\"14\" font-size=\"9.5\" fill=\"#424a50\">Ⅰ类甜点段</text><rect x=\"58\" y=\"3\" width=\"86\" height=\"8\" rx=\"3\" fill=\"#c8c2b4\"/><rect x=\"58\" y=\"13\" width=\"118\" height=\"8\" rx=\"3\" fill=\"#12615a\"/><text x=\"180\" y=\"16\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\">+21.8%</text><text x=\"0\" y=\"48\" font-size=\"9.5\" fill=\"#424a50\">Ⅱ类均质段</text><rect x=\"58\" y=\"37\" width=\"76\" height=\"8\" rx=\"3\" fill=\"#c8c2b4\"/><rect x=\"58\" y=\"47\" width=\"98\" height=\"8\" rx=\"3\" fill=\"#12615a\"/><text x=\"162\" y=\"50\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\">+16.5%</text><text x=\"0\" y=\"82\" font-size=\"9.5\" fill=\"#424a50\">Ⅲ类高应力</text><rect x=\"58\" y=\"71\" width=\"62\" height=\"8\" rx=\"3\" fill=\"#c8c2b4\"/><rect x=\"58\" y=\"81\" width=\"78\" height=\"8\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"142\" y=\"84\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#c27a2c\">+14.2%</text><rect x=\"0\" y=\"100\" width=\"10\" height=\"8\" rx=\"2\" fill=\"#c8c2b4\"/><text x=\"14\" y=\"108\" font-size=\"8.5\" fill=\"#737c83\">传统均匀模版</text><rect x=\"88\" y=\"100\" width=\"10\" height=\"8\" rx=\"2\" fill=\"#12615a\"/><text x=\"102\" y=\"108\" font-size=\"8.5\" fill=\"#12615a\">AI 帕累托定制</text></g></g><g transform=\"translate(510,18)\"><rect x=\"0\" y=\"0\" width=\"232\" height=\"178\" rx=\"8\" fill=\"#fff\" stroke=\"#d9d4c8\"/><text x=\"14\" y=\"22\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">验收三：吨砂与用液产出效率</text><text x=\"14\" y=\"38\" font-size=\"9.5\" fill=\"#737c83\">消除无效过度加砂，提升单位支撑剂贡献</text><g transform=\"translate(16,56)\"><rect x=\"8\" y=\"34\" width=\"32\" height=\"64\" rx=\"3\" fill=\"#c8c2b4\"/><text x=\"24\" y=\"28\" font-size=\"9\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#737c83\" text-anchor=\"middle\">1.42</text><text x=\"24\" y=\"112\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">传统吨砂</text><rect x=\"58\" y=\"14\" width=\"32\" height=\"84\" rx=\"3\" fill=\"#12615a\"/><text x=\"74\" y=\"8\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">1.83</text><text x=\"74\" y=\"112\" font-size=\"8.5\" font-weight=\"600\" fill=\"#12615a\" text-anchor=\"middle\">寻优吨砂</text><rect x=\"114\" y=\"42\" width=\"32\" height=\"56\" rx=\"3\" fill=\"#c8c2b4\"/><text x=\"130\" y=\"36\" font-size=\"9\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#737c83\" text-anchor=\"middle\">0.54</text><text x=\"130\" y=\"112\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">传统均匀度</text><rect x=\"164\" y=\"10\" width=\"32\" height=\"88\" rx=\"3\" fill=\"#2f7d5b\"/><text x=\"180\" y=\"4\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#2f7d5b\" text-anchor=\"middle\">0.89</text><text x=\"180\" y=\"112\" font-size=\"8.5\" font-weight=\"600\" fill=\"#2f7d5b\" text-anchor=\"middle\">寻优均匀度</text></g></g></svg></div><div class=\"figcap\"><b>图 7</b><span>验收指标体系：综合考核代理模型 R²/MAPE 拟合度（左）、三类地质段首年 EUR 增幅（中）以及吨砂产出效率与簇间均匀度提升（右）。</span></div>"},"fails":[{"name":"走滑断层与微裂缝高度发育带诱发套管变形","why":"当压裂段穿越高角度天然走滑断层时，大排量注入引发断层剪切滑移甚至套管错断（套变），常规连续介质代理模型无法预测此类构造失稳，必须切换为降排量防套变模式。"},{"name":"邻井压裂窜扰（Frac-Hit）改变局部地应力场","why":"加密井或同平台拉链式压裂时，老井衰竭区或邻井高压水体使局部最小主应力方向发生偏转，需引入井间干扰修正因子重新标定代理曲面。"},{"name":"超出 LHS 采样边界的极端参数外推失真","why":"若现场尝试超出训练样本范围的超密簇（如 dc < 4 m）或超低粘度清水携砂，神经网络代理模型缺乏物理锚定，必须触发外推告警并回退至物理数模核验。"}]},"demo":{"mode":"auto","html":"demo/index.html","label":"可运行示范","intro":"","height":760}}},"files":[{"name":"demo/index.html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>水平井分段压裂代理模型构建与多目标参数寻优</title>\n<link rel=\"stylesheet\" href=\"demo.css\">\n</head>\n<body>\n<div class=\"app\">\n\n  <!-- 顶栏：仅放 h1 标题与右侧实时状态胶囊，无副标题 -->\n  <header class=\"topbar\">\n    <h1>水平井分段压裂代理模型构建与多目标参数寻优</h1>\n    <div class=\"sp\"></div>\n    <span class=\"pill acc\" id=\"pillZone\"><i></i><span>Ⅰ类高脆甜点段 · BI=0.68</span></span>\n    <span class=\"pill ok\" id=\"pillRisk\"><i></i><span>安全可行域 · 泵压 69.4 MPa</span></span>\n    <span class=\"pill\" id=\"pillSpeed\"><i></i><span class=\"mono\">GPR/MLP 推理 1.1 ms</span></span>\n  </header>\n\n  <!-- 五步流程步进条：与案例流程步骤严格一一对应 -->\n  <nav class=\"stepper\" id=\"stepper\" aria-label=\"案例流程步进\">\n    <button type=\"button\" class=\"done\" data-step=\"0\">\n      <span class=\"n\">STEP 01</span>\n      <span class=\"t\">水平段地质甜点与应力剖面表征</span>\n    </button>\n    <button type=\"button\" class=\"done\" data-step=\"1\">\n      <span class=\"n\">STEP 02</span>\n      <span class=\"t\">拉丁超立方采样与代理模型训练</span>\n    </button>\n    <button type=\"button\" class=\"done\" data-step=\"2\">\n      <span class=\"n\">STEP 03</span>\n      <span class=\"t\">施工压力限值与砂堵安全约束设定</span>\n    </button>\n    <button type=\"button\" class=\"on\" data-step=\"3\">\n      <span class=\"n\">STEP 04</span>\n      <span class=\"t\">多目标帕累托前沿搜索（EUR vs 成本）</span>\n    </button>\n    <button type=\"button\" data-step=\"4\">\n      <span class=\"n\">STEP 05</span>\n      <span class=\"t\">差异化段簇方案输出与微地震验证</span>\n    </button>\n  </nav>\n\n  <!-- 主工作台：左侧参数控制栏 + 右侧双联同步画布 -->\n  <section class=\"bench\">\n    <aside class=\"rail\">\n\n      <!-- 卡片 1：地质甜点段选择 -->\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>1. 水平段地质力学分区</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">单段长 72 m</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"zone-list\" id=\"zoneList\">\n            <button type=\"button\" class=\"zone-btn on\" data-zone=\"z1\">\n              <div class=\"zt\">\n                <span>Ⅰ类高脆甜点段 (BI=0.68)</span>\n                <span class=\"zone-badge\">甜点优选</span>\n              </div>\n              <div class=\"zs\">σh=54.5 MPa · 隔层应力差 Δσ=6.2 MPa</div>\n            </button>\n            <button type=\"button\" class=\"zone-btn\" data-zone=\"z2\">\n              <div class=\"zt\">\n                <span>Ⅱ类致密均质段 (BI=0.52)</span>\n                <span class=\"zone-badge\">中脆稳态</span>\n              </div>\n              <div class=\"zs\">σh=58.0 MPa · 隔层应力差 Δσ=5.0 MPa</div>\n            </button>\n            <button type=\"button\" class=\"zone-btn\" data-zone=\"z3\">\n              <div class=\"zt\">\n                <span>Ⅲ类高应力差隔夹层段 (Δσ=8MPa)</span>\n                <span class=\"zone-badge\">易砂堵/穿层</span>\n              </div>\n              <div class=\"zs\">σh=61.8 MPa · BI=0.41 · 泥质隔夹层发育</div>\n            </button>\n          </div>\n          <div class=\"geo-mini\">\n            <div class=\"geo-cell\">\n              <div class=\"gl\">最小主应力 σh</div>\n              <div class=\"gv\" id=\"geoSigma\">54.5 MPa</div>\n            </div>\n            <div class=\"geo-cell\">\n              <div class=\"gl\">杨氏模量 E</div>\n              <div class=\"gv\" id=\"geoYoung\">38.2 GPa</div>\n            </div>\n            <div class=\"geo-cell\">\n              <div class=\"gl\">天然裂缝密度</div>\n              <div class=\"gv\" id=\"geoFrac\">0.85 条/m</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 卡片 2：压裂工程决策变量滑杆 -->\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>2. 压裂工程决策变量</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">实时驱动代理曲面</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>段内簇数 / 簇间距 m</span>\n              <output id=\"valDc\">6 簇 / 12.0 m</output>\n            </div>\n            <input type=\"range\" id=\"slDc\" min=\"6\" max=\"24\" step=\"0.5\" value=\"12.0\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>施工排量 Q (m³/min)</span>\n              <output id=\"valQ\">14.6 m³/min</output>\n            </div>\n            <input type=\"range\" id=\"slQ\" min=\"8\" max=\"18\" step=\"0.2\" value=\"14.6\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>加砂强度 (t/m)</span>\n              <output id=\"valMp\">2.6 t/m</output>\n            </div>\n            <input type=\"range\" id=\"slMp\" min=\"1.0\" max=\"3.8\" step=\"0.1\" value=\"2.6\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>用液强度 (m³/m)</span>\n              <output id=\"valVf\">25.0 m³/m</output>\n            </div>\n            <input type=\"range\" id=\"slVf\" min=\"12\" max=\"36\" step=\"0.5\" value=\"25.0\">\n          </div>\n\n          <div class=\"divider\"></div>\n\n          <div class=\"btn-stack\">\n            <button type=\"button\" class=\"btn primary block opt-btn\" id=\"btnOptimize\">\n              ★ 一键贝叶斯寻优（跳至当前地质段帕累托最优）\n            </button>\n            <button type=\"button\" class=\"btn block\" id=\"btnUniform\">\n              对比常规均匀方案（dc=9.0m · Q=14.0 · Mp=2.0）\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- 卡片 3：物理场与安全边界图层开关 -->\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>3. 物理场与风险图层</span>\n        </div>\n        <div class=\"card-b\">\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chkShadow\" checked>\n            <span>显示簇间应力阴影干扰场</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chkRisk\" checked>\n            <span>显示隔层穿层与砂堵风险边界</span>\n          </label>\n        </div>\n      </div>\n\n    </aside>\n\n    <!-- 右侧主视图：上下双联同步 Canvas -->\n    <div class=\"stage\">\n\n      <!-- 主画布 1：水平段多簇压裂裂缝扩展几何与应力阴影场俯视/剖面图 -->\n      <div class=\"view\">\n        <div class=\"view-h\">\n          <span>水平段多簇压裂裂缝扩展几何与应力阴影场俯视/剖面图</span>\n          <span class=\"badge-step\" id=\"stepFocusBadge\">STEP 04 · 帕累托最优缝网重构</span>\n          <span class=\"sp\"></span>\n          <span class=\"muted small\" id=\"fracSummaryTxt\">平均半缝长 xf=148 m · 平均缝高 hf=41 m · 有效改造包络 SRV</span>\n        </div>\n        <div class=\"frac-wrap\" id=\"fracWrap\">\n          <canvas id=\"fracCanvas\" width=\"840\" height=\"296\"></canvas>\n          <div class=\"tip\" id=\"fracTip\"></div>\n        </div>\n        <div class=\"view-f\">\n          <div class=\"legend\">\n            <span><i style=\"background:#12615a\"></i>有效支撑裂缝 (高导流铺砂区)</span>\n            <span><i style=\"background:#c27a2c\"></i>应力阴影受抑短簇 (进液受阻)</span>\n            <span><i style=\"background:rgba(180,72,60,0.32);border:1px solid #b4483c\"></i>簇间附加挤压应力阴影场 Δσs</span>\n            <span><i class=\"dash\" style=\"color:#12615a\"></i>有效改造体积 SRV 椭圆包络</span>\n            <span><i class=\"dash\" style=\"color:#b4483c\"></i>上下隔层穿层 / 底水风险红线</span>\n          </div>\n        </div>\n      </div>\n\n      <!-- 主画布 2：2D 代理模型响应曲面等高线图 -->\n      <div class=\"view\">\n        <div class=\"view-h\">\n          <span>2D 代理模型响应曲面等高线图（簇间距 dc × 施工排量 Q → NPV / EUR，点击画布可直接取点）</span>\n          <span class=\"sp\"></span>\n          <div class=\"seg seg-sm\" id=\"surfMetricSeg\">\n            <button type=\"button\" class=\"on\" data-metric=\"npv\">净现值 NPV</button>\n            <button type=\"button\" data-metric=\"eur\">预测 EUR</button>\n            <button type=\"button\" data-metric=\"ui\">簇间均匀度 UI</button>\n          </div>\n        </div>\n        <div class=\"surf-wrap\" id=\"surfWrap\">\n          <canvas id=\"surfCanvas\" width=\"840\" height=\"288\"></canvas>\n          <div class=\"tip\" id=\"surfTip\"></div>\n        </div>\n        <div class=\"view-f\">\n          <div class=\"legend\">\n            <span><i style=\"background:#c27a2c;border-radius:50%\"></i>★ 帕累托最优拐点 (Knee Point)</span>\n            <span><i style=\"background:#ffffff;border:2.5px solid #15191c;border-radius:50%\"></i>● 当前选定压裂方案</span>\n            <span><i style=\"background:#737c83;border-radius:50%\"></i>○ 常规经验均匀方案</span>\n            <span><i style=\"background:rgba(180,72,60,0.28);border:1px dashed #b4483c\"></i>高压砂堵禁区 (Pmax &gt; 85 MPa)</span>\n            <span><i style=\"background:rgba(194,122,44,0.26);border:1px dashed #c27a2c\"></i>大排量隔层穿层边界</span>\n          </div>\n        </div>\n      </div>\n\n    </div>\n  </section>\n\n  <!-- 4 个核心实时 KPI 指标条 -->\n  <section class=\"kpis\">\n    <div class=\"kpi acc\" id=\"kpiSrvCard\">\n      <div class=\"k\">预测改造体积 SRV (万m³)</div>\n      <div class=\"v\" id=\"kpiSrv\">4.68<small>万m³</small></div>\n      <div class=\"d\" id=\"kpiSrvDelta\">较常规均匀方案 +28.2% · 有效缝长 148 m</div>\n    </div>\n    <div class=\"kpi ok\" id=\"kpiEurCard\">\n      <div class=\"k\">预测首年累产 EUR (万m³)</div>\n      <div class=\"v\" id=\"kpiEur\">342.6<small>万m³</small></div>\n      <div class=\"d\" id=\"kpiEurDelta\">较常规均匀方案 +19.8% · 吨砂EUR 1.83</div>\n    </div>\n    <div class=\"kpi ok\" id=\"kpiNpvCard\">\n      <div class=\"k\">单段净现值 NPV (万元)</div>\n      <div class=\"v\" id=\"kpiNpv\">+196.4<small>万元</small></div>\n      <div class=\"d\" id=\"kpiNpvDelta\">单段压裂总成本 146.2 万元 · 净增 +41.5 万</div>\n    </div>\n    <div class=\"kpi ok\" id=\"kpiRiskCard\">\n      <div class=\"k\">簇间均匀度指数 &amp; 砂堵风险</div>\n      <div class=\"v\" id=\"kpiRisk\">0.89<small>低风险 4%</small></div>\n      <div class=\"d\" id=\"kpiRiskDelta\">最高泵压 69.4 MPa (限值85) · 未穿底水层</div>\n    </div>\n  </section>\n\n  <!-- 底部双栏辅助分析 SVG 图 -->\n  <section class=\"grid2\">\n\n    <!-- 左：多目标帕累托前沿散点图 -->\n    <div class=\"view\">\n      <div class=\"view-h\">\n        <span>多目标帕累托前沿散点图（单段改造总成本 vs 预测累产 EUR）</span>\n        <span class=\"sp\"></span>\n        <span class=\"muted small\">NSGA-II 种群 N=120 · 点击散点可切换方案</span>\n      </div>\n      <svg id=\"paretoSvg\" viewBox=\"0 0 540 265\" width=\"100%\" role=\"img\" aria-label=\"多目标帕累托前沿散点图\"></svg>\n      <div class=\"view-f\">\n        <div class=\"legend\">\n          <span><i class=\"line\" style=\"background:#12615a\"></i>帕累托最优前沿 (Pareto Front)</span>\n          <span><i style=\"background:#c27a2c;border-radius:50%\"></i>★ 最大净现值拐点</span>\n          <span><i style=\"background:#15191c;border-radius:50%\"></i>● 当前方案</span>\n          <span><i style=\"background:#737c83;border-radius:50%\"></i>○ 常规均匀方案</span>\n          <span><i style=\"background:#b4483c;border-radius:50%\"></i>× 砂堵/穿层超限方案</span>\n        </div>\n      </div>\n    </div>\n\n    <!-- 右：段内各射孔簇进液/进砂均匀度柱状图 + 施工泵注压力与砂比设计曲线 -->\n    <div class=\"view\">\n      <div class=\"view-h\">\n        <span>段内各射孔簇进液/进砂均匀度柱状图 + 施工泵注压力与砂比设计曲线</span>\n        <span class=\"sp\"></span>\n        <span class=\"muted small\" id=\"pumpSummaryTxt\">阶梯砂比峰值 16.8% · 簇间开启率 100%</span>\n      </div>\n      <svg id=\"clusterSvg\" viewBox=\"0 0 540 265\" width=\"100%\" role=\"img\" aria-label=\"各簇进液进砂均匀度与施工泵注曲线\"></svg>\n      <div class=\"view-f\">\n        <div class=\"legend\">\n          <span><i style=\"background:#12615a\"></i>各簇分流液量占比 (%)</span>\n          <span><i style=\"background:#c27a2c\"></i>各簇支撑剂进砂占比 (%)</span>\n          <span><i class=\"line\" style=\"background:#3a6ea5\"></i>井口施工泵压 P(t)</span>\n          <span><i class=\"line\" style=\"background:#c27a2c\"></i>阶梯砂比浓度 Cprop(t)</span>\n        </div>\n      </div>\n    </div>\n\n  </section>\n\n  <!-- 动态专业解读 -->\n  <section class=\"insight\" id=\"insightBox\">\n    <div class=\"tag\" id=\"insightTag\">寻优诊断 · 帕累托最优态</div>\n    <div id=\"insightText\">\n      正在加载代理模型响应曲面与多簇水力裂缝力学解算器……\n    </div>\n  </section>\n\n</div>\n<script src=\"demo.js\"></script>\n</body>\n</html>\n","enc":"text","size":13195},{"name":"demo/demo.css","data":"/* =========================================================\n   Demo Kit · 案例示范统一样式（每个案例的 demo.css 顶部整段复制本文件）\n   ---------------------------------------------------------\n   运行在沙箱 iframe 里，与主站完全隔离；只用系统字体，离线可用。\n   结构：.app > .topbar + .stepper? + .bench(.rail + .stage) + .kpis + .grid2 + .insight\n   ========================================================= */\n:root{\n  --paper:#f7f5f0; --paper-2:#f0ede5; --surface:#ffffff;\n  --ink:#15191c; --ink-2:#424a50; --ink-3:#737c83; --ink-4:#a3aab0;\n  --line:#e7e3da; --line-2:#d9d4c8;\n  --accent:#12615a; --accent-2:#1d7f75; --accent-l:#e3efec;\n  --amber:#c27a2c; --amber-l:#f7ecdd;\n  --red:#b4483c;  --red-l:#f6e3df;\n  --green:#2f7d5b; --green-l:#e2f0e8;\n  --blue:#3a6ea5; --blue-l:#e3ecf6;\n  --violet:#6b5aa6; --violet-l:#ebe7f5;\n  --sans:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Microsoft YaHei\",\"Noto Sans SC\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"JetBrains Mono\",\"Cascadia Code\",\"SF Mono\",Consolas,ui-monospace,monospace;\n  --r:12px; --r-s:8px;\n  --sh:0 1px 2px rgba(21,25,28,.04),0 6px 24px -12px rgba(21,25,28,.12);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--paper);color:var(--ink)}\nbody{font-family:var(--sans);font-size:13px;line-height:1.7;-webkit-font-smoothing:antialiased;padding:20px 22px 26px}\nb,strong{font-weight:650}\n.mono{font-family:var(--mono)}\n.app{max-width:1160px;margin:0 auto}\n\n/* ---------- 顶栏：只有标题 + 右侧状态胶囊，不放副标题 ---------- */\n.topbar{display:flex;align-items:center;gap:14px;padding-bottom:14px;margin-bottom:16px;border-bottom:1px solid var(--line)}\n.topbar h1{font-size:19px;line-height:1.3;margin:0;letter-spacing:-.01em;font-weight:700}\n.topbar .sp{flex:1}\n.pill{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:999px;font-size:11.5px;\n  border:1px solid var(--line-2);background:var(--surface);color:var(--ink-2);white-space:nowrap}\n.pill i{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block}\n.pill.ok{color:var(--green);border-color:rgba(47,125,91,.28);background:var(--green-l)}\n.pill.warn{color:var(--amber);border-color:rgba(194,122,44,.3);background:var(--amber-l)}\n.pill.bad{color:var(--red);border-color:rgba(180,72,60,.28);background:var(--red-l)}\n.pill.acc{color:var(--accent);border-color:rgba(18,97,90,.25);background:var(--accent-l)}\n\n/* ---------- 流程步进条：与「案例流程」tab 的步骤一一对应 ---------- */\n.stepper{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:0;margin:0 0 16px;\n  background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.stepper button{all:unset;cursor:pointer;position:relative;padding:11px 14px 11px 16px;border-right:1px solid var(--line);\n  display:flex;flex-direction:column;gap:2px;transition:background .18s}\n.stepper button:last-child{border-right:0}\n.stepper button .n{font-family:var(--mono);font-size:10.5px;color:var(--ink-4);letter-spacing:.06em}\n.stepper button .t{font-size:12.5px;font-weight:600;color:var(--ink-2)}\n.stepper button:hover{background:var(--paper)}\n.stepper button.on{background:var(--accent-l)}\n.stepper button.on .n{color:var(--accent)}\n.stepper button.on .t{color:var(--accent)}\n.stepper button.on::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--accent)}\n.stepper button.done .n::after{content:\" ✓\";color:var(--green)}\n\n/* ---------- 工作台：左控制栏 + 右主画布 ---------- */\n.bench{display:grid;grid-template-columns:270px 1fr;gap:16px;align-items:start}\n.rail{display:flex;flex-direction:column;gap:12px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh)}\n.card-h{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);\n  font-size:12px;font-weight:650;color:var(--ink-2)}\n.card-h .sp{flex:1}\n.card-h .hint{font-weight:400;color:var(--ink-4);font-size:11px}\n.card-b{padding:12px 14px}\n.stage{min-width:0;display:flex;flex-direction:column;gap:16px}\n.view{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden}\n.view canvas,.view svg{display:block;width:100%;height:auto}\n.view-h{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);font-size:12px;font-weight:650;color:var(--ink-2)}\n.view-h .sp{flex:1}\n.view-f{display:flex;flex-wrap:wrap;gap:6px 16px;padding:9px 14px;border-top:1px solid var(--line);font-size:11.5px;color:var(--ink-3)}\n\n/* ---------- 控件 ---------- */\n.ctl{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}\n.ctl:last-child{margin-bottom:0}\n.ctl-l{display:flex;align-items:baseline;justify-content:space-between;font-size:12px;color:var(--ink-2)}\n.ctl-l output,.ctl-l .v{font-family:var(--mono);font-size:12px;color:var(--accent);font-weight:600}\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:20px;background:transparent;margin:0}\ninput[type=range]::-webkit-slider-runnable-track{height:4px;border-radius:4px;background:linear-gradient(90deg,var(--accent) var(--p,50%),var(--line) var(--p,50%))}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;border-radius:50%;margin-top:-6px;\n  background:#fff;border:2px solid var(--accent);box-shadow:0 1px 4px rgba(0,0,0,.15)}\ninput[type=range]::-moz-range-track{height:4px;border-radius:4px;background:var(--line)}\ninput[type=range]::-moz-range-progress{height:4px;border-radius:4px;background:var(--accent)}\ninput[type=range]::-moz-range-thumb{width:14px;height:14px;border-radius:50%;background:#fff;border:2px solid var(--accent)}\n.seg{display:flex;background:var(--paper-2);border-radius:9px;padding:3px;gap:3px}\n.seg button{all:unset;flex:1;text-align:center;cursor:pointer;font-size:12px;padding:5px 6px;border-radius:7px;color:var(--ink-3);transition:all .15s}\n.seg button:hover{color:var(--ink)}\n.seg button.on{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:0 1px 3px rgba(0,0,0,.08)}\n.btn{all:unset;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 14px;\n  border-radius:9px;font-size:12.5px;font-weight:600;border:1px solid var(--line-2);background:var(--surface);color:var(--ink);transition:all .15s}\n.btn:hover{border-color:var(--ink-3)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}\n.btn.primary:hover{background:var(--accent-2)}\n.btn.block{display:flex;width:100%;box-sizing:border-box}\n.btn:disabled,.btn.disabled{opacity:.45;pointer-events:none}\n.check{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-2);cursor:pointer;user-select:none;margin:4px 0}\n.check input{accent-color:var(--accent);width:14px;height:14px;margin:0}\n\n/* ---------- 指标条 ---------- */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0;background:var(--surface);\n  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.kpi{padding:12px 16px;border-right:1px solid var(--line)}\n.kpi:last-child{border-right:0}\n.kpi .k{font-size:11px;color:var(--ink-3);letter-spacing:.02em}\n.kpi .v{font-family:var(--mono);font-size:22px;font-weight:600;line-height:1.25;margin-top:3px;letter-spacing:-.02em}\n.kpi .v small{font-size:12px;color:var(--ink-3);font-weight:500;margin-left:3px}\n.kpi .d{font-size:11px;color:var(--ink-4);margin-top:2px}\n.kpi.ok .v{color:var(--green)} .kpi.bad .v{color:var(--red)} .kpi.warn .v{color:var(--amber)} .kpi.acc .v{color:var(--accent)}\n\n/* ---------- 栅格 ---------- */\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n\n/* ---------- 图例 ---------- */\n.legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:11.5px;color:var(--ink-3)}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.legend i{width:10px;height:10px;border-radius:3px;display:inline-block}\n.legend i.line{height:2px;width:14px;border-radius:0}\n.legend i.dash{height:0;width:14px;border-top:2px dashed currentColor;border-radius:0}\n\n/* ---------- 解读：随参数变化的动态说明 ---------- */\n.insight{display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:start;padding:13px 16px;border-radius:var(--r);\n  background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--accent);box-shadow:var(--sh);font-size:12.5px;color:var(--ink-2);line-height:1.8}\n.insight .tag{font-size:11px;font-weight:700;color:var(--accent);letter-spacing:.08em;padding-top:2px;white-space:nowrap}\n.insight.warn{border-left-color:var(--amber)} .insight.warn .tag{color:var(--amber)}\n.insight.bad{border-left-color:var(--red)} .insight.bad .tag{color:var(--red)}\n.insight b{color:var(--ink)}\n\n/* ---------- 表格 ---------- */\ntable.t{width:100%;border-collapse:collapse;font-size:12px}\ntable.t th{text-align:left;font-weight:600;color:var(--ink-3);font-size:11px;padding:7px 10px;border-bottom:1px solid var(--line);background:var(--paper)}\ntable.t td{padding:7px 10px;border-bottom:1px solid var(--line);color:var(--ink-2)}\ntable.t td.num{font-family:var(--mono);text-align:right}\ntable.t tr:last-child td{border-bottom:0}\n\n/* ---------- 浮动提示 ---------- */\n.tip{position:absolute;pointer-events:none;z-index:5;background:rgba(21,25,28,.92);color:#fff;font-size:11.5px;line-height:1.6;\n  padding:7px 10px;border-radius:7px;white-space:nowrap;transform:translate(-50%,calc(-100% - 10px));opacity:0;transition:opacity .12s}\n.tip.on{opacity:1}\n.tip b{color:#fff}\n\n/* ---------- 小工具 ---------- */\n.muted{color:var(--ink-3)} .small{font-size:11.5px}\n.row{display:flex;align-items:center;gap:8px}\n.divider{height:1px;background:var(--line);margin:12px 0}\n.bar{height:6px;border-radius:6px;background:var(--paper-2);overflow:hidden}\n.bar i{display:block;height:100%;border-radius:6px;background:var(--accent);transition:width .3s}\n.fade-in{animation:fi .35s ease both}\n@keyframes fi{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}\n\n@media (max-width:860px){\n  .bench{grid-template-columns:1fr}\n  .grid2,.grid3{grid-template-columns:1fr}\n  .stepper{grid-auto-flow:row}\n  .stepper button{border-right:0;border-bottom:1px solid var(--line)}\n}\n/* ===================== Demo Kit 结束 ===================== */\n\n/* =========================================================\n   本案例专属样式：水平井分段压裂代理模型构建与多目标参数寻优\n   ========================================================= */\n.bench{grid-template-columns:288px 1fr;margin-bottom:16px}\n.kpis{margin-bottom:16px}\n.grid2{margin-bottom:16px}\n\n.zone-list{display:flex;flex-direction:column;gap:6px}\n.zone-btn{all:unset;cursor:pointer;display:flex;flex-direction:column;gap:2px;padding:8px 10px;border-radius:8px;\n  border:1px solid var(--line);background:var(--paper);transition:all .15s}\n.zone-btn:hover{border-color:var(--ink-3);background:var(--surface)}\n.zone-btn.on{border-color:var(--accent);background:var(--accent-l);box-shadow:0 1px 3px rgba(18,97,90,.1)}\n.zone-btn .zt{display:flex;align-items:center;justify-content:space-between;gap:6px;font-size:12px;font-weight:650;color:var(--ink)}\n.zone-btn.on .zt{color:var(--accent)}\n.zone-btn .zs{font-size:11px;color:var(--ink-3);font-family:var(--mono)}\n.zone-badge{font-size:10px;padding:1px 6px;border-radius:99px;font-weight:600;background:var(--surface);border:1px solid var(--line-2);color:var(--ink-2);white-space:nowrap;flex-shrink:0}\n.zone-btn.on .zone-badge{background:var(--accent);border-color:var(--accent);color:#fff}\n\n.btn-stack{display:flex;flex-direction:column;gap:8px;margin-top:4px}\n.btn{min-height:32px;height:auto;padding:6px 12px;line-height:1.3;text-align:center}\n.btn.opt-btn{min-height:34px;font-size:12px;box-shadow:0 2px 8px rgba(18,97,90,.2)}\n\n.geo-mini{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:8px;padding-top:8px;border-top:1px dashed var(--line)}\n.geo-cell{background:var(--paper);border-radius:6px;padding:5px 7px;text-align:center}\n.geo-cell .gl{font-size:10px;color:var(--ink-3);line-height:1.2}\n.geo-cell .gv{font-family:var(--mono);font-size:11.5px;font-weight:650;color:var(--ink);margin-top:2px}\n\n.seg-sm{padding:2px;border-radius:7px}\n.seg-sm button{font-size:11px;padding:3px 8px;border-radius:5px}\n\n.surf-wrap{position:relative;cursor:crosshair}\n.frac-wrap{position:relative;cursor:pointer}\n\n.badge-step{display:inline-flex;align-items:center;gap:5px;padding:2px 8px;border-radius:999px;font-size:11px;\n  font-weight:600;background:var(--accent-l);color:var(--accent);font-family:var(--mono)}\n","enc":"text","size":12837},{"name":"demo/demo.js","data":"(function () {\n  'use strict';\n\n  /* =========================================================\n     1. 地质力学分区参数与固定种子伪随机数生成器\n     ========================================================= */\n  var STAGE_LEN = 72; // 单段长度 72 m\n\n  var ZONES = {\n    z1: {\n      id: 'z1',\n      name: 'Ⅰ类高脆甜点段 (BI=0.68)',\n      shortName: 'Ⅰ类高脆甜点段',\n      bi: 0.68,\n      sigmaH: 54.5,\n      deltaSigma: 6.2,\n      youngE: 38.2,\n      natFrac: 0.85,\n      permFactor: 1.24,\n      shadowLambda: 4.2,\n      barrierH: 48.0,\n      opt: { dc: 12.0, Q: 15.0, Mp: 2.7, Vf: 26.0 },\n      uni: { dc: 9.0, Q: 14.0, Mp: 2.0, Vf: 22.0 }\n    },\n    z2: {\n      id: 'z2',\n      name: 'Ⅱ类致密均质段 (BI=0.52)',\n      shortName: 'Ⅱ类致密均质段',\n      bi: 0.52,\n      sigmaH: 58.0,\n      deltaSigma: 5.0,\n      youngE: 31.5,\n      natFrac: 0.48,\n      permFactor: 1.00,\n      shadowLambda: 4.8,\n      barrierH: 45.0,\n      opt: { dc: 14.5, Q: 13.8, Mp: 2.4, Vf: 24.0 },\n      uni: { dc: 9.0, Q: 14.0, Mp: 2.0, Vf: 22.0 }\n    },\n    z3: {\n      id: 'z3',\n      name: 'Ⅲ类高应力差隔夹层段 (Δσ=8MPa)',\n      shortName: 'Ⅲ类高应力隔夹层段',\n      bi: 0.41,\n      sigmaH: 61.8,\n      deltaSigma: 8.0,\n      youngE: 26.4,\n      natFrac: 0.28,\n      permFactor: 0.82,\n      shadowLambda: 5.5,\n      barrierH: 42.0,\n      opt: { dc: 18.0, Q: 12.4, Mp: 1.9, Vf: 20.5 },\n      uni: { dc: 9.0, Q: 14.0, Mp: 2.0, Vf: 22.0 }\n    }\n  };\n\n  var STEP_META = [\n    {\n      badge: 'STEP 01 · 水平段岩石力学与应力场表征',\n      lead: '当前聚焦【步骤 01：水平段地质甜点与应力剖面表征】。随钻测井反演段内最小水平主应力 σh、脆性指数 BI 与隔层应力差 Δσ，识别沿程非均质甜点边界。'\n    },\n    {\n      badge: 'STEP 02 · LHS 采样与代理响应曲面拟合',\n      lead: '当前聚焦【步骤 02：拉丁超立方采样与代理模型训练】。下方等高线图叠加展示了 28 个 LHS 正交采样点（白圈黑心点），GPR/MLP 代理模型据此在 1.1 ms 内重构出平滑响应面。'\n    },\n    {\n      badge: 'STEP 03 · 砂堵红线与隔层穿层边界裁切',\n      lead: '当前聚焦【步骤 03：施工压力限值与砂堵安全约束设定】。自动标定井口限压 85 MPa 砂堵禁区（左下方红区）与底水穿层边界（右上方琥珀区），将寻优限制在安全可行域 Ω 内。'\n    },\n    {\n      badge: 'STEP 04 · NSGA-II 多目标帕累托全局寻优',\n      lead: '当前聚焦【步骤 04：多目标帕累托前沿搜索（EUR vs 成本）】。在可行域内权衡单段压裂总成本与首年累产 EUR，自动锁定净现值 NPV 最高的帕累托拐点 ★。'\n    },\n    {\n      badge: 'STEP 05 · 差异化段簇方案与微地震 SRV 验证',\n      lead: '当前聚焦【步骤 05：差异化段簇方案输出与微地震验证】。右上俯视图叠加微地震监测事件云点，检验定制段簇方案的簇间均匀开启率与实际 SRV 包络吻合度。'\n    }\n  ];\n\n  var state = {\n    zone: 'z1',\n    step: 3,\n    dc: 12.0,\n    Q: 15.0,\n    Mp: 2.7,\n    Vf: 26.0,\n    showShadow: true,\n    showRisk: true,\n    surfMetric: 'npv',\n    animating: false,\n    searchTrail: [],\n    hoverCluster: -1\n  };\n\n  function mulberry32(seed) {\n    return function () {\n      var t = (seed += 0x6D2B79F5);\n      t = Math.imul(t ^ (t >>> 15), t | 1);\n      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    };\n  }\n\n  /* 生成固定种子的 LHS 采样点用于展示 */\n  var lhsPoints = (function () {\n    var rng = mulberry32(20261101);\n    var n = 24;\n    var xs = [], ys = [];\n    for (var i = 0; i < n; i++) {\n      xs.push((i + 0.15 + 0.7 * rng()) / n);\n      ys.push((i + 0.15 + 0.7 * rng()) / n);\n    }\n    for (var j = n - 1; j > 0; j--) {\n      var k = Math.floor(rng() * (j + 1));\n      var tmp = ys[j]; ys[j] = ys[k]; ys[k] = tmp;\n    }\n    var out = [];\n    for (var m = 0; m < n; m++) {\n      out.push({\n        dc: 6 + xs[m] * 18,\n        Q: 8 + ys[m] * 10\n      });\n    }\n    return out;\n  })();\n\n  /* =========================================================\n     2. 物理约束代理模型核心解算器 (1.1 ms 级实时计算)\n     ========================================================= */\n  function evaluateSurrogate(zoneKey, dc, Q, Mp, Vf) {\n    var z = ZONES[zoneKey];\n    var Nc = Math.max(3, Math.min(12, Math.round(STAGE_LEN / dc)));\n    var actualDc = STAGE_LEN / Nc;\n\n    // 簇间应力阴影干扰强度：簇间距越小、排量越大、杨氏模量越高，中间簇受挤压越剧烈\n    var shadowSeverity = Math.exp(-(dc - 5.2) / z.shadowLambda) * (0.72 + 0.028 * (Q - 8)) * (0.85 + 0.008 * (z.youngE - 30));\n    shadowSeverity = Math.max(0.03, Math.min(1.35, shadowSeverity));\n\n    var clusters = [];\n    var rawFluidWeights = [];\n    var rawPropWeights = [];\n    var sumF = 0, sumP = 0;\n\n    for (var i = 0; i < Nc; i++) {\n      // 归一化簇位置 u ∈ [-1, 1]\n      var u = Nc === 1 ? 0 : (2 * i / (Nc - 1)) - 1;\n      // 中间簇受两侧外簇挤压附加应力 Δσs (MPa)\n      var centerFactor = 1 - 0.82 * u * u;\n      var deltaSigmaS = shadowSeverity * centerFactor * 7.8;\n\n      // 进液权重：中间簇因局部最小主应力抬升而进液受阻，外侧簇抢液\n      var wFluid = Math.exp(-deltaSigmaS / 3.4) * (1 + 0.22 * u * u * shadowSeverity);\n      // 支撑剂由于惯性与沉降效应，在窄缝/受抑簇中更难进入\n      var wProp = Math.pow(wFluid, 1.28);\n\n      rawFluidWeights.push(wFluid);\n      rawPropWeights.push(wProp);\n      sumF += wFluid;\n      sumP += wProp;\n      clusters.push({\n        index: i + 1,\n        u: u,\n        deltaSigmaS: deltaSigmaS,\n        fluidShare: 0,\n        propShare: 0,\n        xf: 0,\n        hf: 0,\n        widthMm: 0,\n        stunted: false,\n        breach: false\n      });\n    }\n\n    // 计算簇间均匀度指数 UI (Uniformity Index)\n    var idealShare = 1 / Nc;\n    var devSum = 0;\n    for (var c = 0; c < Nc; c++) {\n      var fs = rawFluidWeights[c] / sumF;\n      var ps = rawPropWeights[c] / sumP;\n      clusters[c].fluidShare = fs;\n      clusters[c].propShare = ps;\n      devSum += Math.abs(fs - idealShare);\n    }\n    var UI = Math.max(0.18, Math.min(0.98, 1 - 0.68 * (devSum / (2 * (1 - idealShare)))));\n\n    // 计算各簇裂缝几何：半缝长 xf (m)、缝高 hf (m)、缝宽 (mm)\n    var totalFluidM3 = Vf * STAGE_LEN; // 单段总液量 m³\n    var totalPropTon = Mp * STAGE_LEN; // 单段总砂量 t\n    var avgXf = 0, maxHf = 0, avgHf = 0;\n\n    for (var k = 0; k < Nc; k++) {\n      var cl = clusters[k];\n      var clusterFluid = totalFluidM3 * cl.fluidShare;\n      var clusterProp = totalPropTon * cl.propShare;\n      var qCluster = Q * cl.fluidShare;\n\n      // 半缝长受单簇进液量、脆性指数和支撑剂铺置效率共同控制\n      var xf = 112 * Math.pow(clusterFluid / 280, 0.52) * (0.78 + 0.42 * z.bi) * Math.pow(Math.max(0.4, clusterProp / 28), 0.18);\n      xf = Math.max(36, Math.min(215, xf));\n\n      // 缝高受局部单簇排量、施工总排量与隔层应力差 Δσ 控制\n      var qNorm = qCluster / 2.35;\n      var excessQ = Math.max(0, Q - (z.id === 'z1' ? 15.8 : z.id === 'z2' ? 15.0 : 13.8));\n      var tightOuterBoost = (dc < 9.2 && Math.abs(cl.u) > 0.65) ? (9.2 - dc) * 2.4 : 0;\n      var hf = 25.5 + 12.8 * Math.pow(qNorm, 0.58) + 2.8 * excessQ + tightOuterBoost - 0.85 * (z.deltaSigma - 5.0);\n      hf = Math.max(18, Math.min(64, hf));\n\n      var widthMm = 2.2 + 2.5 * Math.pow(clusterProp / 28, 0.62) * Math.pow(cl.fluidShare * Nc, 0.45);\n      widthMm = Math.max(1.2, Math.min(9.5, widthMm));\n\n      cl.xf = xf;\n      cl.hf = hf;\n      cl.widthMm = widthMm;\n      cl.stunted = (cl.fluidShare < idealShare * 0.74) || (cl.deltaSigmaS > 3.6);\n      cl.breach = hf > z.barrierH;\n\n      avgXf += xf;\n      avgHf += hf;\n      if (hf > maxHf) maxHf = hf;\n    }\n    avgXf /= Nc;\n    avgHf /= Nc;\n\n    // 井口最高施工泵压 Pmax (MPa) 与砂堵风险概率计算\n    // 当簇间距过密引发强烈应力阴影，或高砂比低排量携砂困难，或排量超高孔眼摩阻剧增时，诱发高压砂堵\n    var avgSandRatio = (totalPropTon / Math.max(1, totalFluidM3)) * 100; // 平均体积质量砂比 %\n    var perfFriction = 3.2 * Math.pow(Q / Math.max(3.5, Nc * 0.82), 1.45) * (1 + 0.4 * (1 - UI));\n    var slurryPenalty = Math.max(0, (avgSandRatio - 11.2) * 2.2) * (1 + 0.75 * Math.max(0, 12.8 - Q) / 4.0);\n    var tightShadowPress = Math.max(0, 10.2 - dc) * 3.15 * Math.pow(Mp / 2.2, 0.85);\n    var shadowPressPenalty = shadowSeverity * 5.2 * Math.pow(Mp / 2.3, 1.05) + tightShadowPress;\n    var pMax = z.sigmaH + 4.8 + 0.52 * (Q - 10) + perfFriction + slurryPenalty + shadowPressPenalty;\n    pMax = Math.max(54, Math.min(104, pMax));\n\n    // 砂堵概率 (Screenout Risk 0 ~ 100%)\n    var screenoutScore = (pMax - 82.5) / 4.2 + (avgSandRatio - 13.5) / 2.6 + (0.64 - UI) * 4.5;\n    if (z.id === 'z3') screenoutScore += 0.45 * Math.max(0, Mp - 2.2);\n    var screenoutProb = 100 / (1 + Math.exp(-1.55 * screenoutScore));\n    screenoutProb = Math.max(2, Math.min(99, screenoutProb));\n\n    var isScreenout = pMax > 85.0 || screenoutProb > 48;\n    var isBarrierBreach = maxHf > z.barrierH;\n\n    // 有效改造体积 SRV (万m³)：考虑簇间应力阴影折减、最优簇数覆盖度与支撑剂铺置效率\n    var dcMatchEff = Math.exp(-Math.pow((dc - z.opt.dc) / 6.8, 2));\n    var proppantPlacementEff = Math.exp(-Math.pow((Mp - z.opt.Mp) / 1.65, 2)) * (0.72 + 0.28 * UI);\n    var fluidMatchEff = Math.exp(-Math.pow((Vf - z.opt.Vf) / 12.5, 2));\n    var rateMatchEff = Math.exp(-Math.pow((Q - z.opt.Q) / 4.0, 2));\n\n    var srv = (2.15 + 2.65 * z.bi + 0.55 * Math.pow(Vf / 24, 0.45) + 0.45 * Math.pow(Mp / 2.5, 0.4))\n      * (0.58 + 0.42 * dcMatchEff)\n      * (0.65 + 0.35 * UI)\n      * (0.78 + 0.22 * rateMatchEff);\n    srv = Math.max(1.2, Math.min(5.8, srv));\n\n    // 预测首年累产 EUR (万m³)\n    var breachWaterPenalty = isBarrierBreach ? Math.min(0.32, (maxHf - z.barrierH) * 0.032) : 0;\n    var screenoutPenalty = isScreenout ? Math.min(0.38, Math.max(0.08, (screenoutProb - 35) * 0.0065)) : 0;\n    var eur = 94 * Math.pow(srv, 0.72) * z.permFactor * (0.74 + 0.26 * proppantPlacementEff) * (0.86 + 0.14 * fluidMatchEff) * (1 - breachWaterPenalty) * (1 - screenoutPenalty);\n    eur = Math.max(90, Math.min(430, eur));\n\n    // 单段压裂总成本 Cost (万元)：桥塞射孔 + 压裂液成本 + 支撑剂成本 + 泵车台时功率费\n    var costPlugPerf = 16.0 + 2.8 * Nc;\n    var costFluid = 0.019 * totalFluidM3; // 万m³滑溜水折算万元\n    var costProp = 0.32 * totalPropTon;   // 支撑剂万元\n    var costPump = 1.45 * Math.pow(Q, 1.15) * (1 + Math.max(0, pMax - 72) * 0.015);\n    var cost = costPlugPerf + costFluid + costProp + costPump;\n\n    // 单段净现值 NPV (万元)：油气边际收益折现 - 压裂直接成本 - 砂堵/穿底水风险期望损失\n    var riskExpectedLoss = (isScreenout ? 38 + (screenoutProb - 35) * 0.9 : (screenoutProb > 20 ? (screenoutProb - 20) * 0.6 : 0))\n      + (isBarrierBreach ? 32 + (maxHf - z.barrierH) * 5.2 : 0);\n    var npv = eur * 1.02 - cost - riskExpectedLoss - 12.0 * Math.pow((dc - z.opt.dc) / 6.0, 2) - 8.0 * Math.pow((Q - z.opt.Q) / 3.5, 2);\n\n    return {\n      zone: z,\n      dc: dc,\n      actualDc: actualDc,\n      Nc: Nc,\n      Q: Q,\n      Mp: Mp,\n      Vf: Vf,\n      UI: UI,\n      avgXf: avgXf,\n      avgHf: avgHf,\n      maxHf: maxHf,\n      pMax: pMax,\n      avgSandRatio: avgSandRatio,\n      screenoutProb: screenoutProb,\n      isScreenout: isScreenout,\n      isBarrierBreach: isBarrierBreach,\n      srv: srv,\n      eur: eur,\n      cost: cost,\n      npv: npv,\n      tonSandEur: eur / Math.max(1, totalPropTon),\n      clusters: clusters\n    };\n  }\n  /* =========================================================\n     3. 生成当前地质段的候选方案集与帕累托前沿 (NSGA-II)\n     ========================================================= */\n  function buildParetoPopulation(zoneKey) {\n    var rng = mulberry32(zoneKey === 'z1' ? 101 : zoneKey === 'z2' ? 202 : 303);\n    var z = ZONES[zoneKey];\n    var pop = [];\n\n    // 合成 96 个覆盖参数空间的候选方案\n    for (var i = 0; i < 96; i++) {\n      var dc = 6.0 + rng() * 18.0;\n      var Q = 8.0 + rng() * 10.0;\n      var Mp = 1.0 + rng() * 2.8;\n      var Vf = 12.0 + rng() * 24.0;\n      // 让一部分点向帕累托前沿附近聚集以增强可看性\n      if (i % 3 === 0) {\n        dc = z.opt.dc + (rng() - 0.5) * 6.5;\n        Q = z.opt.Q + (rng() - 0.5) * 4.2;\n        Mp = 1.1 + (i / 96) * 2.6;\n        Vf = 14.0 + (i / 96) * 20.0;\n      }\n      dc = Math.max(6, Math.min(24, Math.round(dc * 2) / 2));\n      Q = Math.max(8, Math.min(18, Math.round(Q * 5) / 5));\n      Mp = Math.max(1.0, Math.min(3.8, Math.round(Mp * 10) / 10));\n      Vf = Math.max(12, Math.min(36, Math.round(Vf * 2) / 2));\n      var res = evaluateSurrogate(zoneKey, dc, Q, Mp, Vf);\n      pop.push(res);\n    }\n\n    // 加入该地质段的帕累托最优拐点方案与常规均匀方案\n    var optRes = evaluateSurrogate(zoneKey, z.opt.dc, z.opt.Q, z.opt.Mp, z.opt.Vf);\n    optRes.isOptAnchor = true;\n    pop.push(optRes);\n\n    // 提取安全可行域内的非支配解集 (Pareto Front: 成本更低 或 EUR更高)\n    var feasible = pop.filter(function (p) { return !p.isScreenout && !p.isBarrierBreach; });\n    feasible.sort(function (a, b) { return a.cost - b.cost; });\n\n    var front = [];\n    var maxEurSoFar = -Infinity;\n    for (var j = 0; j < feasible.length; j++) {\n      if (feasible[j].eur > maxEurSoFar + 1.2) {\n        front.push(feasible[j]);\n        maxEurSoFar = feasible[j].eur;\n      }\n    }\n\n    // 找出最大净现值拐点 (Knee Point)\n    var knee = optRes;\n    for (var k = 0; k < front.length; k++) {\n      if (front[k].npv > knee.npv) knee = front[k];\n    }\n\n    return { pop: pop, front: front, knee: knee, optRes: optRes };\n  }\n\n  /* =========================================================\n     4. Canvas 工具：高分屏自适应初始化\n     ========================================================= */\n  function setupCanvas(canvas, cssW, cssH) {\n    var dpr = Math.min(2, window.devicePixelRatio || 1);\n    if (canvas.width !== Math.round(cssW * dpr) || canvas.height !== Math.round(cssH * dpr)) {\n      canvas.width = Math.round(cssW * dpr);\n      canvas.height = Math.round(cssH * dpr);\n    }\n    var ctx = canvas.getContext('2d');\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n    return ctx;\n  }\n\n  /* =========================================================\n     5. 主视图 1：水平段多簇水力裂缝几何与应力阴影场绘制\n     ========================================================= */\n  var clusterHitBoxes = [];\n\n  function drawFractureCanvas(cur) {\n    var canvas = document.getElementById('fracCanvas');\n    var W = 840, H = 296;\n    var ctx = setupCanvas(canvas, W, H);\n    ctx.clearRect(0, 0, W, H);\n\n    var z = cur.zone;\n    // 左侧 62% 绘制【正视地质剖面：缝高 hf + 簇间应力阴影干扰 + 隔层穿层边界】\n    // 右侧 38% 绘制【俯视水平段平面：半缝长 xf + SRV 包络 + 微地震点】\n    var splitX = 516;\n\n    /* --- A. 左半区：水平段纵剖面 (X: 16..504, Y: 28..268) --- */\n    var px0 = 18, py0 = 28, pw = 486, ph = 246;\n    var wellY = py0 + ph * 0.5;\n    // 比例尺：纵向上下各代表 34m 高度 (共68m)\n    var mToY = (ph * 0.5) / 34.0;\n    var barrierHalfPx = (z.barrierH * 0.5) * mToY;\n    var topBarrierY = wellY - barrierHalfPx;\n    var botBarrierY = wellY + barrierHalfPx;\n\n    // 储层背景与上下隔层\n    var bgGrad = ctx.createLinearGradient(0, py0, 0, py0 + ph);\n    bgGrad.addColorStop(0, '#dad3c5');\n    bgGrad.addColorStop(0.18, '#efe9dc');\n    bgGrad.addColorStop(0.82, '#ebe4d5');\n    bgGrad.addColorStop(1, '#c8d6e2');\n    ctx.fillStyle = bgGrad;\n    ctx.fillRect(px0, py0, pw, ph);\n\n    // 上部高应力泥岩遮挡层 & 下部含水风险层\n    ctx.fillStyle = 'rgba(140, 122, 107, 0.24)';\n    ctx.fillRect(px0, py0, pw, Math.max(0, topBarrierY - py0));\n    ctx.fillStyle = 'rgba(58, 110, 165, 0.22)';\n    ctx.fillRect(px0, botBarrierY, pw, Math.max(0, py0 + ph - botBarrierY));\n\n    // Step 01 时绘制沿程岩石力学应力/脆性背景条带\n    if (state.step === 0) {\n      for (var s = 0; s < 16; s++) {\n        var sx = px0 + (s / 16) * pw;\n        var wave = Math.sin(s * 0.8 + (z.id === 'z1' ? 0 : z.id === 'z2' ? 1.5 : 3.1));\n        ctx.fillStyle = z.id === 'z1'\n          ? 'rgba(18, 97, 90, ' + (0.06 + 0.04 * wave) + ')'\n          : z.id === 'z2'\n            ? 'rgba(58, 110, 165, ' + (0.06 + 0.03 * wave) + ')'\n            : 'rgba(194, 122, 44, ' + (0.08 + 0.04 * wave) + ')';\n        ctx.fillRect(sx, topBarrierY, pw / 16 + 1, botBarrierY - topBarrierY);\n      }\n    }\n\n    // 隔层与底水风险边界虚线\n    if (state.showRisk) {\n      ctx.save();\n      ctx.setLineDash([5, 3]);\n      ctx.strokeStyle = '#8c7a6b';\n      ctx.lineWidth = 1.2;\n      ctx.beginPath();\n      ctx.moveTo(px0, topBarrierY);\n      ctx.lineTo(px0 + pw, topBarrierY);\n      ctx.stroke();\n\n      ctx.strokeStyle = '#b4483c';\n      ctx.lineWidth = 1.4;\n      ctx.beginPath();\n      ctx.moveTo(px0, botBarrierY);\n      ctx.lineTo(px0 + pw, botBarrierY);\n      ctx.stroke();\n      ctx.restore();\n\n      ctx.fillStyle = '#5c5248';\n      ctx.font = '10.5px sans-serif';\n      ctx.fillText('上部泥岩遮挡层 (Δσ=' + z.deltaSigma.toFixed(1) + ' MPa · 安全控缝高上限)', px0 + 8, topBarrierY - 5);\n      ctx.fillStyle = '#b4483c';\n      ctx.fillText('下部底水/隔层穿层红线 (一旦突破含水率暴增)', px0 + 8, botBarrierY + 13);\n    }\n\n    // 桥塞位置与段长范围\n    var stageLeft = px0 + 42;\n    var stageRight = px0 + pw - 42;\n    var stageSpan = stageRight - stageLeft;\n\n    clusterHitBoxes = [];\n    var Nc = cur.Nc;\n\n    // 1) 绘制簇间应力阴影干扰场 + SRV 椭圆包络\n    for (var i = 0; i < Nc; i++) {\n      var cl = cur.clusters[i];\n      var cx = Nc === 1 ? (stageLeft + stageRight) / 2 : stageLeft + (i + 0.5) * (stageSpan / Nc);\n      var halfH = (cl.hf * 0.5) * mToY;\n\n      // SRV 改造椭圆包络\n      ctx.save();\n      var srvRx = Math.max(14, (stageSpan / Nc) * 0.58 * (cl.stunted ? 0.65 : 1.05));\n      var srvGrad = ctx.createRadialGradient(cx, wellY, 3, cx, wellY, Math.max(srvRx, halfH));\n      srvGrad.addColorStop(0, 'rgba(18, 97, 90, 0.20)');\n      srvGrad.addColorStop(0.75, 'rgba(18, 97, 90, 0.07)');\n      srvGrad.addColorStop(1, 'rgba(18, 97, 90, 0)');\n      ctx.fillStyle = srvGrad;\n      ctx.beginPath();\n      ctx.ellipse(cx, wellY, srvRx, halfH * 0.96, 0, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.setLineDash([3, 2]);\n      ctx.strokeStyle = 'rgba(18, 97, 90, 0.45)';\n      ctx.lineWidth = 1;\n      ctx.stroke();\n      ctx.restore();\n\n      // 应力阴影附加挤压光晕与挤压箭头\n      if (state.showShadow && cl.deltaSigmaS > 1.8) {\n        var shAlpha = Math.min(0.42, (cl.deltaSigmaS / 8.5) * 0.42);\n        var shRx = Math.max(16, (stageSpan / Nc) * 0.65);\n        var shGrad = ctx.createRadialGradient(cx, wellY, 2, cx, wellY, shRx * 1.35);\n        shGrad.addColorStop(0, 'rgba(180, 72, 60, ' + shAlpha + ')');\n        shGrad.addColorStop(0.7, 'rgba(194, 122, 44, ' + (shAlpha * 0.5) + ')');\n        shGrad.addColorStop(1, 'rgba(194, 122, 44, 0)');\n        ctx.fillStyle = shGrad;\n        ctx.beginPath();\n        ctx.ellipse(cx, wellY, shRx * 1.2, halfH * 0.85, 0, 0, Math.PI * 2);\n        ctx.fill();\n      }\n    }\n\n    // 2) 绘制水平井筒与两侧桥塞\n    ctx.fillStyle = '#3a4248';\n    ctx.fillRect(px0 + 10, wellY - 4, pw - 20, 8);\n    // 左桥塞 & 右桥塞\n    ctx.fillStyle = '#15191c';\n    ctx.fillRect(stageLeft - 8, wellY - 9, 8, 18);\n    ctx.fillRect(stageRight, wellY - 9, 8, 18);\n\n    // 3) 绘制每簇水力裂缝剖面形态、支撑剂填充及穿层告警\n    for (var j = 0; j < Nc; j++) {\n      var cObj = cur.clusters[j];\n      var fx = Nc === 1 ? (stageLeft + stageRight) / 2 : stageLeft + (j + 0.5) * (stageSpan / Nc);\n      var fHalfH = (cObj.hf * 0.5) * mToY;\n      var halfW = Math.max(2.2, Math.min(7.2, cObj.widthMm * 0.85));\n\n      var isHovered = (state.hoverCluster === j);\n      var fracColor = cObj.breach ? '#b4483c' : (cObj.stunted ? '#c27a2c' : '#12615a');\n\n      ctx.save();\n      ctx.beginPath();\n      ctx.moveTo(fx - halfW, wellY);\n      ctx.quadraticCurveTo(fx - halfW * 0.65, wellY - fHalfH * 0.65, fx, wellY - fHalfH);\n      ctx.quadraticCurveTo(fx + halfW * 0.65, wellY - fHalfH * 0.65, fx + halfW, wellY);\n      ctx.quadraticCurveTo(fx + halfW * 0.65, wellY + fHalfH * 0.65, fx, wellY + fHalfH);\n      ctx.quadraticCurveTo(fx - halfW * 0.65, wellY + fHalfH * 0.65, fx - halfW, wellY);\n      ctx.closePath();\n\n      ctx.fillStyle = fracColor;\n      ctx.globalAlpha = isHovered ? 0.98 : 0.86;\n      ctx.fill();\n      if (isHovered) {\n        ctx.strokeStyle = '#15191c';\n        ctx.lineWidth = 1.6;\n        ctx.stroke();\n      }\n      ctx.restore();\n\n      // 支撑剂高导流核心区（琥珀色内芯）\n      var propHalfH = fHalfH * Math.min(0.84, 0.52 + 0.1 * cur.Mp);\n      ctx.save();\n      ctx.beginPath();\n      ctx.ellipse(fx, wellY, Math.max(1.2, halfW * 0.45), propHalfH, 0, 0, Math.PI * 2);\n      ctx.fillStyle = '#f3c677';\n      ctx.globalAlpha = 0.85;\n      ctx.fill();\n      ctx.restore();\n\n      // 簇间挤压双向箭头示意（当受抑严重时）\n      if (state.showShadow && cObj.stunted && j > 0 && j < Nc - 1) {\n        ctx.save();\n        ctx.strokeStyle = '#b4483c';\n        ctx.lineWidth = 1.3;\n        var arrY = wellY - fHalfH - 8;\n        ctx.beginPath();\n        ctx.moveTo(fx - 13, arrY);\n        ctx.lineTo(fx - 4, arrY);\n        ctx.moveTo(fx + 13, arrY);\n        ctx.lineTo(fx + 4, arrY);\n        ctx.stroke();\n        ctx.fillStyle = '#b4483c';\n        ctx.font = 'bold 9px monospace';\n        ctx.textAlign = 'center';\n        ctx.fillText('+' + cObj.deltaSigmaS.toFixed(1) + 'MPa', fx, arrY - 3);\n        ctx.restore();\n      }\n\n      // 穿层告警闪烁圆环\n      if (state.showRisk && cObj.breach) {\n        ctx.save();\n        ctx.strokeStyle = '#b4483c';\n        ctx.lineWidth = 2;\n        ctx.beginPath();\n        ctx.arc(fx, wellY + fHalfH - 2, 7, 0, Math.PI * 2);\n        ctx.stroke();\n        ctx.restore();\n      }\n\n      // 簇编号与半缝长标注\n      ctx.fillStyle = cObj.stunted ? '#9e5816' : '#15191c';\n      ctx.font = 'bold 10px monospace';\n      ctx.textAlign = 'center';\n      ctx.fillText('#' + (j + 1), fx, wellY + 18);\n\n      clusterHitBoxes.push({\n        idx: j,\n        x0: fx - Math.max(14, stageSpan / Nc / 2),\n        x1: fx + Math.max(14, stageSpan / Nc / 2),\n        y0: py0,\n        y1: py0 + ph,\n        cx: fx,\n        cy: wellY - fHalfH * 0.5\n      });\n    }\n\n    // 剖面图边框与标题角标\n    ctx.strokeStyle = '#d9d4c8';\n    ctx.lineWidth = 1;\n    ctx.strokeRect(px0, py0, pw, ph);\n    ctx.fillStyle = '#15191c';\n    ctx.font = 'bold 11.5px sans-serif';\n    ctx.textAlign = 'left';\n    ctx.fillText('A. 水平段纵剖面：缝高扩展 hf 与簇间应力阴影场 (段长 72m · ' + Nc + ' 簇)', px0, 19);\n\n    /* --- B. 右半区：俯视水平井平面缝网与微地震 SRV 包络 (X: 524..822, Y: 28..268) --- */\n    var rx0 = 524, ry0 = 28, rw = 298, rh = 246;\n    var rWellY = ry0 + rh * 0.5;\n    // 比例尺：俯视上下各代表 210 m 半缝长 xf\n    var xfToPx = (rh * 0.5 - 14) / 210.0;\n\n    ctx.fillStyle = '#fbfaf7';\n    ctx.fillRect(rx0, ry0, rw, rh);\n\n    // 俯视比例网格线 (-150m, -75m, 0, +75m, +150m)\n    ctx.save();\n    ctx.strokeStyle = '#ebe7de';\n    ctx.lineWidth = 1;\n    [-150, -75, 75, 150].forEach(function (m) {\n      var gy = rWellY - m * xfToPx;\n      ctx.beginPath();\n      ctx.moveTo(rx0, gy);\n      ctx.lineTo(rx0 + rw, gy);\n      ctx.stroke();\n      ctx.fillStyle = '#9aa2a8';\n      ctx.font = '9.5px monospace';\n      ctx.textAlign = 'right';\n      ctx.fillText(Math.abs(m) + 'm', rx0 + rw - 4, gy - 2);\n    });\n    ctx.restore();\n\n    var pStageLeft = rx0 + 28;\n    var pStageRight = rx0 + rw - 38;\n    var pStageSpan = pStageRight - pStageLeft;\n\n    // 俯视 SRV 改造区与双翼水力裂缝\n    var rngMs = mulberry32(7788 + Nc * 13);\n    for (var mIdx = 0; mIdx < Nc; mIdx++) {\n      var mc = cur.clusters[mIdx];\n      var mcx = Nc === 1 ? (pStageLeft + pStageRight) / 2 : pStageLeft + (mIdx + 0.5) * (pStageSpan / Nc);\n      var mHalfLen = mc.xf * xfToPx;\n\n      // 俯视 SRV 椭圆\n      ctx.save();\n      ctx.fillStyle = mc.stunted ? 'rgba(194, 122, 44, 0.14)' : 'rgba(18, 97, 90, 0.16)';\n      ctx.strokeStyle = mc.stunted ? 'rgba(194, 122, 44, 0.55)' : 'rgba(18, 97, 90, 0.55)';\n      ctx.setLineDash([3, 2]);\n      ctx.beginPath();\n      ctx.ellipse(mcx, rWellY, Math.max(8, (pStageSpan / Nc) * 0.52), mHalfLen, 0, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.stroke();\n      ctx.restore();\n\n      // 双翼主裂缝线\n      ctx.save();\n      ctx.strokeStyle = mc.breach ? '#b4483c' : (mc.stunted ? '#c27a2c' : '#12615a');\n      ctx.lineWidth = Math.max(1.8, Math.min(4.5, mc.widthMm * 0.65));\n      ctx.beginPath();\n      ctx.moveTo(mcx, rWellY - mHalfLen);\n      ctx.lineTo(mcx, rWellY + mHalfLen);\n      ctx.stroke();\n      ctx.restore();\n\n      // 微地震事件云点（Step 05 时强化高亮，其余步骤半透明展示）\n      var msCount = state.step === 4 ? 14 : 6;\n      ctx.fillStyle = state.step === 4 ? '#12615a' : 'rgba(18, 97, 90, 0.45)';\n      for (var d = 0; d < msCount; d++) {\n        var dx = (rngMs() - 0.5) * (pStageSpan / Nc) * 0.85;\n        var dy = (rngMs() - 0.5) * 2 * mHalfLen * 0.92;\n        ctx.beginPath();\n        ctx.arc(mcx + dx, rWellY + dy, state.step === 4 ? 2.1 : 1.5, 0, Math.PI * 2);\n        ctx.fill();\n      }\n    }\n\n    // 俯视井筒\n    ctx.fillStyle = '#3a4248';\n    ctx.fillRect(rx0 + 10, rWellY - 3, rw - 24, 6);\n\n    ctx.strokeStyle = '#d9d4c8';\n    ctx.lineWidth = 1;\n    ctx.strokeRect(rx0, ry0, rw, rh);\n    ctx.fillStyle = '#15191c';\n    ctx.font = 'bold 11.5px sans-serif';\n    ctx.textAlign = 'left';\n    ctx.fillText('B. 俯视平面：半缝长 xf 与微地震 SRV', rx0, 19);\n\n    // 底部状态角标：若有砂堵或穿层立即在画布上给出醒目提示\n    if (cur.isScreenout || cur.isBarrierBreach) {\n      var warnTxt = cur.isScreenout && cur.isBarrierBreach\n        ? '⚠ 告警：当前参数同时触发【高压砂堵 Pmax=' + cur.pMax.toFixed(1) + 'MPa】与【底水隔层穿层】！'\n        : cur.isScreenout\n          ? '⚠ 告警：簇间不均/砂比过高触发【早期砂堵风险 ' + cur.screenoutProb.toFixed(0) + '% · Pmax=' + cur.pMax.toFixed(1) + 'MPa】！'\n          : '⚠ 告警：外侧簇净压力过高【突破下部底水隔层 (最大缝高 ' + cur.maxHf.toFixed(1) + 'm > 限值 ' + z.barrierH.toFixed(0) + 'm)】！';\n      ctx.fillStyle = 'rgba(180, 72, 60, 0.92)';\n      ctx.fillRect(px0 + 8, py0 + ph - 26, pw - 16, 20);\n      ctx.fillStyle = '#ffffff';\n      ctx.font = 'bold 10.5px sans-serif';\n      ctx.fillText(warnTxt, px0 + 16, py0 + ph - 12);\n    }\n\n    document.getElementById('fracSummaryTxt').textContent =\n      '平均半缝长 xf=' + cur.avgXf.toFixed(0) + ' m · 平均缝高 hf=' + cur.avgHf.toFixed(1) + ' m · 簇间均匀度 UI=' + cur.UI.toFixed(2);\n  }\n  /* =========================================================\n     6. 主视图 2：2D 代理模型响应曲面等高线图 (dc × Q → NPV/EUR/UI)\n     ========================================================= */\n  var surfPlotBox = { x0: 56, y0: 20, w: 668, h: 232 };\n\n  function valToColor(t) {\n    // t ∈ [0, 1]: 低值冷灰蓝 -> 中值青绿 -> 高值深翡翠绿与暖金\n    t = Math.max(0, Math.min(1, t));\n    var r, g, b;\n    if (t < 0.45) {\n      var u = t / 0.45;\n      r = Math.round(232 - u * 44);\n      g = Math.round(238 - u * 18);\n      b = Math.round(244 - u * 34);\n    } else if (t < 0.82) {\n      var v = (t - 0.45) / 0.37;\n      r = Math.round(188 - v * 136);\n      g = Math.round(220 - v * 72);\n      b = Math.round(210 - v * 78);\n    } else {\n      var w = (t - 0.82) / 0.18;\n      r = Math.round(52 - w * 28);\n      g = Math.round(148 - w * 42);\n      b = Math.round(132 - w * 36);\n    }\n    return 'rgb(' + r + ',' + g + ',' + b + ')';\n  }\n\n  function drawSurfaceCanvas(cur, paretoData) {\n    var canvas = document.getElementById('surfCanvas');\n    var W = 840, H = 288;\n    var ctx = setupCanvas(canvas, W, H);\n    ctx.clearRect(0, 0, W, H);\n\n    var bx = surfPlotBox.x0, by = surfPlotBox.y0, bw = surfPlotBox.w, bh = surfPlotBox.h;\n    var cols = 56, rows = 36;\n    var cellW = bw / cols, cellH = bh / rows;\n\n    var grid = [];\n    var minV = Infinity, maxV = -Infinity;\n    var bestCell = { dc: cur.zone.opt.dc, Q: cur.zone.opt.Q, val: -Infinity };\n\n    for (var r = 0; r < rows; r++) {\n      var rowArr = [];\n      // y轴从上到下对应 Q 从 18 到 8 m³/min\n      var qVal = 18.0 - (r + 0.5) / rows * 10.0;\n      for (var c = 0; c < cols; c++) {\n        // x轴从左到右对应 dc 从 6 到 24 m\n        var dcVal = 6.0 + (c + 0.5) / cols * 18.0;\n        var sim = evaluateSurrogate(state.zone, dcVal, qVal, state.Mp, state.Vf);\n        var mVal = state.surfMetric === 'npv' ? sim.npv : (state.surfMetric === 'eur' ? sim.eur : sim.UI);\n        if (mVal < minV) minV = mVal;\n        if (mVal > maxV) maxV = mVal;\n        if (!sim.isScreenout && !sim.isBarrierBreach && mVal > bestCell.val) {\n          bestCell = { dc: dcVal, Q: qVal, val: mVal, sim: sim };\n        }\n        rowArr.push({ dc: dcVal, Q: qVal, val: mVal, sim: sim });\n      }\n      grid.push(rowArr);\n    }\n\n    var span = Math.max(1e-5, maxV - minV);\n\n    // 1) 绘制响应曲面栅格与风险阴影区\n    for (var rr = 0; rr < rows; rr++) {\n      for (var cc = 0; cc < cols; cc++) {\n        var cell = grid[rr][cc];\n        var norm = (cell.val - minV) / span;\n        var cx = bx + cc * cellW;\n        var cy = by + rr * cellH;\n        ctx.fillStyle = valToColor(norm);\n        ctx.fillRect(cx, cy, Math.ceil(cellW), Math.ceil(cellH));\n\n        if (state.showRisk) {\n          if (cell.sim.isScreenout) {\n            ctx.fillStyle = 'rgba(180, 72, 60, 0.34)';\n            ctx.fillRect(cx, cy, Math.ceil(cellW), Math.ceil(cellH));\n          } else if (cell.sim.isBarrierBreach) {\n            ctx.fillStyle = 'rgba(194, 122, 44, 0.30)';\n            ctx.fillRect(cx, cy, Math.ceil(cellW), Math.ceil(cellH));\n          }\n        }\n      }\n    }\n\n    // 2) 绘制等高线 (Iso-contours)\n    var levels = [0.25, 0.45, 0.65, 0.82, 0.93];\n    ctx.save();\n    ctx.strokeStyle = 'rgba(21, 25, 28, 0.24)';\n    ctx.lineWidth = 1;\n    for (var lv = 0; lv < levels.length; lv++) {\n      var target = minV + levels[lv] * span;\n      ctx.beginPath();\n      for (var r1 = 0; r1 < rows - 1; r1++) {\n        for (var c1 = 0; c1 < cols - 1; c1++) {\n          var v00 = grid[r1][c1].val - target;\n          var v10 = grid[r1][c1 + 1].val - target;\n          var v01 = grid[r1 + 1][c1].val - target;\n          if ((v00 * v10 < 0) || (v00 * v01 < 0)) {\n            var px = bx + (c1 + 0.5) * cellW;\n            var py = by + (r1 + 0.5) * cellH;\n            ctx.rect(px, py, 1.2, 1.2);\n          }\n        }\n      }\n      ctx.stroke();\n    }\n    ctx.restore();\n\n    // 3) 标注砂堵禁区与穿层边界文字\n    if (state.showRisk) {\n      ctx.save();\n      ctx.fillStyle = '#8f291e';\n      ctx.font = 'bold 10.5px sans-serif';\n      ctx.fillText('⛔ 高压砂堵禁区 (Pmax > 85 MPa)', bx + 10, by + 22);\n      ctx.fillStyle = '#8c5215';\n      ctx.fillText('⚠ 隔层穿层边界 (大排量缝高超限)', bx + bw - 195, by + 22);\n      ctx.restore();\n    }\n\n    // 4) 绘制 LHS 采样点（Step 02 时高亮放大，其余步骤淡化展示）\n    ctx.save();\n    for (var i = 0; i < lhsPoints.length; i++) {\n      var lp = lhsPoints[i];\n      var lx = bx + ((lp.dc - 6) / 18) * bw;\n      var ly = by + ((18 - lp.Q) / 10) * bh;\n      ctx.beginPath();\n      ctx.arc(lx, ly, state.step === 1 ? 3.8 : 2.2, 0, Math.PI * 2);\n      ctx.fillStyle = state.step === 1 ? '#ffffff' : 'rgba(255,255,255,0.65)';\n      ctx.fill();\n      ctx.strokeStyle = state.step === 1 ? '#12615a' : 'rgba(21,25,28,0.4)';\n      ctx.lineWidth = state.step === 1 ? 1.6 : 1;\n      ctx.stroke();\n    }\n    ctx.restore();\n\n    // 5) 绘制贝叶斯寻优迭代轨迹（若用户点击过一键寻优）\n    if (state.searchTrail && state.searchTrail.length > 1) {\n      ctx.save();\n      ctx.strokeStyle = '#c27a2c';\n      ctx.lineWidth = 2;\n      ctx.setLineDash([4, 3]);\n      ctx.beginPath();\n      for (var t = 0; t < state.searchTrail.length; t++) {\n        var tp = state.searchTrail[t];\n        var tx = bx + ((tp.dc - 6) / 18) * bw;\n        var ty = by + ((18 - tp.Q) / 10) * bh;\n        if (t === 0) ctx.moveTo(tx, ty);\n        else ctx.lineTo(tx, ty);\n      }\n      ctx.stroke();\n      ctx.restore();\n    }\n\n    // 6) 绘制常规经验均匀方案点 ○\n    var uni = cur.zone.uni;\n    var ux = bx + ((uni.dc - 6) / 18) * bw;\n    var uy = by + ((18 - uni.Q) / 10) * bh;\n    ctx.save();\n    ctx.beginPath();\n    ctx.arc(ux, uy, 5.5, 0, Math.PI * 2);\n    ctx.fillStyle = '#737c83';\n    ctx.fill();\n    ctx.strokeStyle = '#ffffff';\n    ctx.lineWidth = 1.8;\n    ctx.stroke();\n    ctx.fillStyle = '#424a50';\n    ctx.font = 'bold 10px sans-serif';\n    ctx.fillText('○ 常规均匀方案', ux + 8, uy + 4);\n    ctx.restore();\n\n    // 7) 绘制当前(Mp, Vf)截面下的帕累托最优点 ★\n    var ox = bx + ((bestCell.dc - 6) / 18) * bw;\n    var oy = by + ((18 - bestCell.Q) / 10) * bh;\n    ctx.save();\n    ctx.beginPath();\n    ctx.arc(ox, oy, 7.5, 0, Math.PI * 2);\n    ctx.fillStyle = '#c27a2c';\n    ctx.fill();\n    ctx.strokeStyle = '#ffffff';\n    ctx.lineWidth = 2;\n    ctx.stroke();\n    ctx.fillStyle = '#ffffff';\n    ctx.font = 'bold 9.5px sans-serif';\n    ctx.textAlign = 'center';\n    ctx.fillText('★', ox, oy + 3.5);\n    ctx.fillStyle = '#15191c';\n    ctx.font = 'bold 10.5px sans-serif';\n    ctx.textAlign = 'left';\n    ctx.fillText('★ 代理曲面最优 (' + bestCell.dc.toFixed(1) + 'm, ' + bestCell.Q.toFixed(1) + ')', ox + 10, oy - 4);\n    ctx.restore();\n\n    // 8) 绘制当前用户选定工作点 ●\n    var curX = bx + ((cur.dc - 6) / 18) * bw;\n    var curY = by + ((18 - cur.Q) / 10) * bh;\n    ctx.save();\n    // 十字准星线\n    ctx.strokeStyle = 'rgba(21, 25, 28, 0.45)';\n    ctx.setLineDash([3, 3]);\n    ctx.beginPath();\n    ctx.moveTo(curX, by);\n    ctx.lineTo(curX, by + bh);\n    ctx.moveTo(bx, curY);\n    ctx.lineTo(bx + bw, curY);\n    ctx.stroke();\n\n    ctx.beginPath();\n    ctx.arc(curX, curY, 6.5, 0, Math.PI * 2);\n    ctx.fillStyle = '#ffffff';\n    ctx.fill();\n    ctx.strokeStyle = cur.isScreenout || cur.isBarrierBreach ? '#b4483c' : '#15191c';\n    ctx.lineWidth = 3;\n    ctx.stroke();\n    ctx.restore();\n\n    // 9) 坐标轴刻度与右侧色标条\n    ctx.strokeStyle = '#737c83';\n    ctx.lineWidth = 1;\n    ctx.strokeRect(bx, by, bw, bh);\n\n    ctx.fillStyle = '#424a50';\n    ctx.font = '10px monospace';\n    ctx.textAlign = 'center';\n    for (var dTick = 6; dTick <= 24; dTick += 3) {\n      var txTick = bx + ((dTick - 6) / 18) * bw;\n      ctx.fillText(dTick + 'm', txTick, by + bh + 14);\n    }\n    ctx.font = 'bold 10.5px sans-serif';\n    ctx.fillText('段内射孔簇间距 dc (m) → [点击或拖动曲面可直接调参]', bx + bw / 2, by + bh + 29);\n\n    ctx.font = '10px monospace';\n    ctx.textAlign = 'right';\n    for (var qTick = 8; qTick <= 18; qTick += 2) {\n      var tyTick = by + ((18 - qTick) / 10) * bh;\n      ctx.fillText(qTick + '', bx - 6, tyTick + 3);\n    }\n    ctx.save();\n    ctx.translate(16, by + bh / 2);\n    ctx.rotate(-Math.PI / 2);\n    ctx.font = 'bold 10.5px sans-serif';\n    ctx.textAlign = 'center';\n    ctx.fillText('施工排量 Q (m³/min) →', 0, 0);\n    ctx.restore();\n\n    // 右侧连续色标 Legend Bar\n    var legX = bx + bw + 18, legY = by + 10, legW = 14, legH = bh - 20;\n    for (var lyIdx = 0; lyIdx < legH; lyIdx++) {\n      var ratio = 1 - lyIdx / legH;\n      ctx.fillStyle = valToColor(ratio);\n      ctx.fillRect(legX, legY + lyIdx, legW, 1.5);\n    }\n    ctx.strokeStyle = '#d9d4c8';\n    ctx.strokeRect(legX, legY, legW, legH);\n    ctx.fillStyle = '#424a50';\n    ctx.font = '9.5px monospace';\n    ctx.textAlign = 'left';\n    var unitStr = state.surfMetric === 'npv' ? '万' : (state.surfMetric === 'eur' ? '万方' : '');\n    ctx.fillText(maxV.toFixed(state.surfMetric === 'ui' ? 2 : 0) + unitStr, legX + 18, legY + 8);\n    ctx.fillText(((maxV + minV) * 0.5).toFixed(state.surfMetric === 'ui' ? 2 : 0) + unitStr, legX + 18, legY + legH / 2 + 3);\n    ctx.fillText(minV.toFixed(state.surfMetric === 'ui' ? 2 : 0) + unitStr, legX + 18, legY + legH);\n  }\n\n  /* =========================================================\n     7. 底部左图：多目标帕累托前沿散点图 (SVG)\n     ========================================================= */\n  function drawParetoSvg(cur, paretoData) {\n    var svg = document.getElementById('paretoSvg');\n    var z = cur.zone;\n    var uniRes = evaluateSurrogate(state.zone, z.uni.dc, z.uni.Q, z.uni.Mp, z.uni.Vf);\n\n    var allPts = paretoData.pop.concat([cur, uniRes]);\n    var minCost = Infinity, maxCost = -Infinity, minEur = Infinity, maxEur = -Infinity;\n    for (var i = 0; i < allPts.length; i++) {\n      if (allPts[i].cost < minCost) minCost = allPts[i].cost;\n      if (allPts[i].cost > maxCost) maxCost = allPts[i].cost;\n      if (allPts[i].eur < minEur) minEur = allPts[i].eur;\n      if (allPts[i].eur > maxEur) maxEur = allPts[i].eur;\n    }\n    minCost = Math.floor(minCost * 0.92);\n    maxCost = Math.ceil(maxCost * 1.06);\n    minEur = Math.floor(minEur * 0.90);\n    maxEur = Math.ceil(maxEur * 1.08);\n\n    var px0 = 52, py0 = 18, pw = 464, ph = 206;\n    function toX(c) { return px0 + ((c - minCost) / Math.max(1, maxCost - minCost)) * pw; }\n    function toY(e) { return py0 + ph - ((e - minEur) / Math.max(1, maxEur - minEur)) * ph; }\n\n    var html = [];\n    html.push('<rect x=\"' + px0 + '\" y=\"' + py0 + '\" width=\"' + pw + '\" height=\"' + ph + '\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>');\n\n    // 网格与坐标刻度\n    for (var g = 0; g <= 4; g++) {\n      var cVal = minCost + (g / 4) * (maxCost - minCost);\n      var gx = toX(cVal);\n      html.push('<line x1=\"' + gx.toFixed(1) + '\" y1=\"' + py0 + '\" x2=\"' + gx.toFixed(1) + '\" y2=\"' + (py0 + ph) + '\" stroke=\"#ece8df\"/>');\n      html.push('<text x=\"' + gx.toFixed(1) + '\" y=\"' + (py0 + ph + 15) + '\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#737c83\" text-anchor=\"middle\">' + cVal.toFixed(0) + '</text>');\n\n      var eVal = minEur + (g / 4) * (maxEur - minEur);\n      var gy = toY(eVal);\n      html.push('<line x1=\"' + px0 + '\" y1=\"' + gy.toFixed(1) + '\" x2=\"' + (px0 + pw) + '\" y2=\"' + gy.toFixed(1) + '\" stroke=\"#ece8df\"/>');\n      html.push('<text x=\"' + (px0 - 6) + '\" y=\"' + (gy + 3).toFixed(1) + '\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#737c83\" text-anchor=\"end\">' + eVal.toFixed(0) + '</text>');\n    }\n\n    html.push('<text x=\"' + (px0 + pw / 2) + '\" y=\"' + (py0 + ph + 33) + '\" font-size=\"10.5\" font-weight=\"600\" fill=\"#424a50\" text-anchor=\"middle\">单段压裂改造总成本 Cost (万元) →</text>');\n    html.push('<text x=\"15\" y=\"' + (py0 + ph / 2) + '\" font-size=\"10.5\" font-weight=\"600\" fill=\"#424a50\" text-anchor=\"middle\" transform=\"rotate(-90 15 ' + (py0 + ph / 2) + ')\">预测首年累产 EUR (万m³) →</text>');\n\n    // 候选散点（区分可行解与砂堵/穿层超限解）\n    for (var pIdx = 0; pIdx < paretoData.pop.length; pIdx++) {\n      var pt = paretoData.pop[pIdx];\n      var cx = toX(pt.cost), cy = toY(pt.eur);\n      if (pt.isScreenout || pt.isBarrierBreach) {\n        html.push('<circle class=\"pt-cand\" data-idx=\"' + pIdx + '\" cx=\"' + cx.toFixed(1) + '\" cy=\"' + cy.toFixed(1) + '\" r=\"3.2\" fill=\"#f6e3df\" stroke=\"#b4483c\" stroke-width=\"1\" style=\"cursor:pointer\"/>');\n      } else {\n        html.push('<circle class=\"pt-cand\" data-idx=\"' + pIdx + '\" cx=\"' + cx.toFixed(1) + '\" cy=\"' + cy.toFixed(1) + '\" r=\"3.5\" fill=\"#a9b8b4\" fill-opacity=\"0.65\" stroke=\"#12615a\" stroke-opacity=\"0.4\" style=\"cursor:pointer\"/>');\n      }\n    }\n\n    // 帕累托最优前沿连线与节点\n    if (paretoData.front.length > 1) {\n      var dPath = paretoData.front.map(function (fp, idx) {\n        return (idx === 0 ? 'M' : 'L') + toX(fp.cost).toFixed(1) + ',' + toY(fp.eur).toFixed(1);\n      }).join(' ');\n      html.push('<path d=\"' + dPath + '\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.4\"/>');\n      paretoData.front.forEach(function (fp) {\n        html.push('<circle cx=\"' + toX(fp.cost).toFixed(1) + '\" cy=\"' + toY(fp.eur).toFixed(1) + '\" r=\"4.2\" fill=\"#12615a\" stroke=\"#fff\" stroke-width=\"1\"/>');\n      });\n    }\n\n    // 常规均匀方案点 ○\n    var ux = toX(uniRes.cost), uy = toY(uniRes.eur);\n    html.push('<circle cx=\"' + ux.toFixed(1) + '\" cy=\"' + uy.toFixed(1) + '\" r=\"5.5\" fill=\"#737c83\" stroke=\"#fff\" stroke-width=\"1.5\"/>');\n    html.push('<text x=\"' + (ux + 8).toFixed(1) + '\" y=\"' + (uy + 13).toFixed(1) + '\" font-size=\"9.5\" font-weight=\"600\" fill=\"#525a60\">○ 常规均匀 (NPV +' + uniRes.npv.toFixed(0) + '万)</text>');\n\n    // 帕累托最大 NPV 拐点 ★\n    var kx = toX(paretoData.knee.cost), ky = toY(paretoData.knee.eur);\n    html.push('<circle cx=\"' + kx.toFixed(1) + '\" cy=\"' + ky.toFixed(1) + '\" r=\"7\" fill=\"#c27a2c\" stroke=\"#fff\" stroke-width=\"1.8\"/>');\n    html.push('<text x=\"' + kx.toFixed(1) + '\" y=\"' + Math.max(30, ky - 11).toFixed(1) + '\" font-size=\"10\" font-weight=\"700\" fill=\"#c27a2c\" text-anchor=\"middle\">★ 帕累托最优拐点 (NPV +' + paretoData.knee.npv.toFixed(0) + '万)</text>');\n\n    // 当前选定方案点 ●\n    var curX = toX(cur.cost), curY = toY(cur.eur);\n    var curColor = (cur.isScreenout || cur.isBarrierBreach) ? '#b4483c' : '#15191c';\n    html.push('<circle cx=\"' + curX.toFixed(1) + '\" cy=\"' + curY.toFixed(1) + '\" r=\"5.8\" fill=\"#fff\" stroke=\"' + curColor + '\" stroke-width=\"2.8\"/>');\n    var distToKnee = Math.hypot(curX - kx, curY - ky);\n    var curLblY = distToKnee < 65 ? curY + 19 : curY - 9;\n    html.push('<text x=\"' + (curX + 9).toFixed(1) + '\" y=\"' + curLblY.toFixed(1) + '\" font-size=\"9.5\" font-weight=\"700\" fill=\"' + curColor + '\">● 当前 (' + cur.cost.toFixed(0) + '万, ' + cur.eur.toFixed(0) + '万方)</text>');\n\n    svg.innerHTML = html.join('');\n\n    // 允许点击帕累托图上的候选散点直接切换参数\n    var circles = svg.querySelectorAll('.pt-cand');\n    circles.forEach(function (el) {\n      el.addEventListener('click', function () {\n        var idx = +el.getAttribute('data-idx');\n        var chosen = paretoData.pop[idx];\n        if (chosen) applyParams(chosen.dc, chosen.Q, chosen.Mp, chosen.Vf);\n      });\n    });\n  }\n\n  /* =========================================================\n     8. 底部右图：各簇进液/进砂均匀度柱状图 + 施工泵注程序曲线 (SVG)\n     ========================================================= */\n  function drawClusterSvg(cur) {\n    var svg = document.getElementById('clusterSvg');\n    var html = [];\n\n    // 左半区 (X: 38..262)：各簇分流液量占比 vs 进砂占比柱状图\n    var lx0 = 38, ly0 = 24, lw = 224, lh = 198;\n    html.push('<rect x=\"' + lx0 + '\" y=\"' + ly0 + '\" width=\"' + lw + '\" height=\"' + lh + '\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>');\n    html.push('<text x=\"' + lx0 + '\" y=\"15\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\">A. 段内各射孔簇进液/进砂均匀度</text>');\n\n    var Nc = cur.Nc;\n    var idealPct = 100 / Nc;\n    var maxPct = Math.max(36, idealPct * 2.1);\n    var idealY = ly0 + lh - (idealPct / maxPct) * lh;\n\n    // 理想均匀基准线\n    html.push('<line x1=\"' + lx0 + '\" y1=\"' + idealY.toFixed(1) + '\" x2=\"' + (lx0 + lw) + '\" y2=\"' + idealY.toFixed(1) + '\" stroke=\"#12615a\" stroke-width=\"1.3\" stroke-dasharray=\"4,3\"/>');\n    html.push('<text x=\"' + (lx0 + lw - 4) + '\" y=\"' + (idealY - 4).toFixed(1) + '\" font-size=\"8.5\" font-weight=\"600\" fill=\"#12615a\" text-anchor=\"end\">理想均分线 ' + idealPct.toFixed(1) + '%</text>');\n\n    var slotW = lw / Nc;\n    var barW = Math.min(11, Math.max(4.5, slotW * 0.34));\n    var activeClusters = 0;\n\n    for (var i = 0; i < Nc; i++) {\n      var cl = cur.clusters[i];\n      var fPct = cl.fluidShare * 100;\n      var pPct = cl.propShare * 100;\n      if (fPct >= idealPct * 0.55) activeClusters++;\n\n      var fH = Math.min(lh - 4, (fPct / maxPct) * lh);\n      var pH = Math.min(lh - 4, (pPct / maxPct) * lh);\n      var centerX = lx0 + (i + 0.5) * slotW;\n\n      var fColor = cl.stunted ? '#b4483c' : '#12615a';\n      html.push('<rect x=\"' + (centerX - barW - 1).toFixed(1) + '\" y=\"' + (ly0 + lh - fH).toFixed(1) + '\" width=\"' + barW.toFixed(1) + '\" height=\"' + fH.toFixed(1) + '\" rx=\"1.5\" fill=\"' + fColor + '\"/>');\n      html.push('<rect x=\"' + (centerX + 1).toFixed(1) + '\" y=\"' + (ly0 + lh - pH).toFixed(1) + '\" width=\"' + barW.toFixed(1) + '\" height=\"' + pH.toFixed(1) + '\" rx=\"1.5\" fill=\"#c27a2c\"/>');\n      html.push('<text x=\"' + centerX.toFixed(1) + '\" y=\"' + (ly0 + lh + 13) + '\" font-size=\"8.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#424a50\" text-anchor=\"middle\">#' + (i + 1) + '</text>');\n    }\n    html.push('<text x=\"' + (lx0 + lw / 2) + '\" y=\"' + (ly0 + lh + 29) + '\" font-size=\"10\" font-weight=\"600\" fill=\"#424a50\" text-anchor=\"middle\">射孔簇编号 (均匀度 UI=' + cur.UI.toFixed(2) + ')</text>');\n\n    // 右半区 (X: 296..522)：施工泵注压力 P(t) 与阶梯砂比设计曲线\n    var rx0 = 296, ry0 = 24, rw = 226, rh = 198;\n    html.push('<rect x=\"' + rx0 + '\" y=\"' + ry0 + '\" width=\"' + rw + '\" height=\"' + rh + '\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>');\n    html.push('<text x=\"' + rx0 + '\" y=\"15\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\">B. 施工泵压 P(t) 与阶梯砂比曲线</text>');\n\n    // 85 MPa 井口安全限压红线\n    var pLimY = ry0 + rh - ((85 - 40) / 65) * rh;\n    html.push('<line x1=\"' + rx0 + '\" y1=\"' + pLimY.toFixed(1) + '\" x2=\"' + (rx0 + rw) + '\" y2=\"' + pLimY.toFixed(1) + '\" stroke=\"#b4483c\" stroke-width=\"1.3\" stroke-dasharray=\"4,3\"/>');\n    html.push('<text x=\"' + (rx0 + 6) + '\" y=\"' + (pLimY - 4).toFixed(1) + '\" font-size=\"8.5\" font-weight=\"700\" fill=\"#b4483c\">井口限压红线 85 MPa</text>');\n\n    // 构造 0~100% 泵注进度的压力曲线与阶梯砂比曲线\n    var pPts = [];\n    var sPts = [];\n    var peakSandPct = cur.avgSandRatio * 1.42;\n    for (var s = 0; s <= 24; s++) {\n      var u = s / 24;\n      var sx = rx0 + u * rw;\n      // 阶梯砂比：前置液 (0~0.18) -> 4级阶梯加砂 (0.18~0.88) -> 顶替液 (0.88~1.0)\n      var sandRatio = 0;\n      if (u >= 0.18 && u < 0.35) sandRatio = peakSandPct * 0.38;\n      else if (u >= 0.35 && u < 0.55) sandRatio = peakSandPct * 0.65;\n      else if (u >= 0.55 && u < 0.74) sandRatio = peakSandPct * 0.86;\n      else if (u >= 0.74 && u <= 0.88) sandRatio = peakSandPct * 1.00;\n\n      var sy = ry0 + rh - Math.min(rh - 6, (sandRatio / 28) * rh);\n      sPts.push((s === 0 ? 'M' : 'L') + sx.toFixed(1) + ',' + sy.toFixed(1));\n\n      // 施工泵压 P(t)：破裂尖峰 (u=0.08) -> 稳态扩展 -> 尾端加砂摩阻爬升（若砂堵则尾端急剧翘起突破85MPa）\n      var pVal;\n      if (u < 0.08) {\n        pVal = 45 + (u / 0.08) * (cur.zone.sigmaH + 13 - 45);\n      } else if (u < 0.65) {\n        pVal = cur.zone.sigmaH + 6.5 + 0.45 * (cur.Q - 10) + Math.sin(u * 18) * 0.8;\n      } else {\n        var tail = (u - 0.65) / 0.35;\n        pVal = (cur.zone.sigmaH + 7.2 + 0.45 * (cur.Q - 10)) + Math.pow(tail, 1.65) * (cur.pMax - (cur.zone.sigmaH + 7.2));\n      }\n      var py = ry0 + rh - Math.max(4, Math.min(rh - 4, ((pVal - 40) / 65) * rh));\n      pPts.push((s === 0 ? 'M' : 'L') + sx.toFixed(1) + ',' + py.toFixed(1));\n    }\n\n    html.push('<path d=\"' + sPts.join(' ') + '\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"2\"/>');\n    var pStroke = cur.isScreenout ? '#b4483c' : '#3a6ea5';\n    html.push('<path d=\"' + pPts.join(' ') + '\" fill=\"none\" stroke=\"' + pStroke + '\" stroke-width=\"2.2\"/>');\n\n    if (cur.isScreenout) {\n      html.push('<circle cx=\"' + (rx0 + rw * 0.92).toFixed(1) + '\" cy=\"' + (pLimY - 8).toFixed(1) + '\" r=\"4.5\" fill=\"#b4483c\"/>');\n      html.push('<text x=\"' + (rx0 + rw - 6) + '\" y=\"' + (pLimY + 13).toFixed(1) + '\" font-size=\"8.5\" font-weight=\"700\" fill=\"#b4483c\" text-anchor=\"end\">尾端砂堵憋压！</text>');\n    }\n\n    html.push('<text x=\"' + (rx0 + rw / 2) + '\" y=\"' + (ry0 + rh + 29) + '\" font-size=\"10\" font-weight=\"600\" fill=\"#424a50\" text-anchor=\"middle\">单段泵注施工进度 (0 → 90 min)</text>');\n\n    svg.innerHTML = html.join('');\n\n    var openRate = Math.round((activeClusters / Nc) * 100);\n    document.getElementById('pumpSummaryTxt').textContent =\n      '阶梯砂比峰值 ' + peakSandPct.toFixed(1) + '% · 有效开启率 ' + openRate + '%';\n  }\n\n  /* =========================================================\n     9. 顶栏胶囊、KPI 卡片与动态专业解读同步更新\n     ========================================================= */\n  function updateKpisAndInsight(cur, paretoData) {\n    var z = cur.zone;\n    var uni = evaluateSurrogate(state.zone, z.uni.dc, z.uni.Q, z.uni.Mp, z.uni.Vf);\n\n    // 更新滑杆旁数值与进度条百分比\n    function syncSlider(id, outId, val, min, max, fmt) {\n      var el = document.getElementById(id);\n      var pct = ((val - min) / (max - min)) * 100;\n      el.value = val;\n      el.style.setProperty('--p', pct.toFixed(1) + '%');\n      document.getElementById(outId).textContent = fmt;\n    }\n\n    syncSlider('slDc', 'valDc', cur.dc, 6, 24, cur.Nc + ' 簇 / ' + cur.dc.toFixed(1) + ' m');\n    syncSlider('slQ', 'valQ', cur.Q, 8, 18, cur.Q.toFixed(1) + ' m³/min');\n    syncSlider('slMp', 'valMp', cur.Mp, 1.0, 3.8, cur.Mp.toFixed(1) + ' t/m');\n    syncSlider('slVf', 'valVf', cur.Vf, 12, 36, cur.Vf.toFixed(1) + ' m³/m');\n\n    // 岩石力学小卡片\n    document.getElementById('geoSigma').textContent = z.sigmaH.toFixed(1) + ' MPa';\n    document.getElementById('geoYoung').textContent = z.youngE.toFixed(1) + ' GPa';\n    document.getElementById('geoFrac').textContent = z.natFrac.toFixed(2) + ' 条/m';\n\n    // 顶栏胶囊\n    document.getElementById('pillZone').innerHTML = '<i></i><span>' + z.name + '</span>';\n    var pillRisk = document.getElementById('pillRisk');\n    if (cur.isScreenout || cur.isBarrierBreach) {\n      pillRisk.className = 'pill bad';\n      pillRisk.innerHTML = '<i></i><span>' + (cur.isScreenout ? '砂堵超限' : '隔层穿层') + ' · 泵压 ' + cur.pMax.toFixed(1) + ' MPa</span>';\n    } else if (cur.UI < 0.72 || cur.screenoutProb > 25) {\n      pillRisk.className = 'pill warn';\n      pillRisk.innerHTML = '<i></i><span>次优警告 · 泵压 ' + cur.pMax.toFixed(1) + ' MPa</span>';\n    } else {\n      pillRisk.className = 'pill ok';\n      pillRisk.innerHTML = '<i></i><span>安全可行域 · 泵压 ' + cur.pMax.toFixed(1) + ' MPa</span>';\n    }\n\n    // 4 个 KPI 指标卡\n    var srvDeltaPct = ((cur.srv - uni.srv) / uni.srv) * 100;\n    var eurDeltaPct = ((cur.eur - uni.eur) / uni.eur) * 100;\n    var npvDelta = cur.npv - uni.npv;\n\n    document.getElementById('kpiSrv').innerHTML = cur.srv.toFixed(2) + '<small>万m³</small>';\n    document.getElementById('kpiSrvDelta').textContent =\n      '较常规均匀方案 ' + (srvDeltaPct >= 0 ? '+' : '') + srvDeltaPct.toFixed(1) + '% · 平均半缝长 ' + cur.avgXf.toFixed(0) + ' m';\n\n    document.getElementById('kpiEur').innerHTML = cur.eur.toFixed(1) + '<small>万m³</small>';\n    document.getElementById('kpiEurDelta').textContent =\n      '较常规均匀方案 ' + (eurDeltaPct >= 0 ? '+' : '') + eurDeltaPct.toFixed(1) + '% · 吨砂EUR ' + cur.tonSandEur.toFixed(2);\n    document.getElementById('kpiEurCard').className = 'kpi ' + (eurDeltaPct >= 5 ? 'ok' : (eurDeltaPct >= 0 ? 'acc' : 'warn'));\n\n    document.getElementById('kpiNpv').innerHTML = (cur.npv >= 0 ? '+' : '') + cur.npv.toFixed(1) + '<small>万元</small>';\n    document.getElementById('kpiNpvDelta').textContent =\n      '单段总成本 ' + cur.cost.toFixed(1) + ' 万元 · 较常规 ' + (npvDelta >= 0 ? '+' : '') + npvDelta.toFixed(1) + ' 万';\n    document.getElementById('kpiNpvCard').className = 'kpi ' + (npvDelta >= 15 ? 'ok' : (npvDelta >= 0 ? 'acc' : 'bad'));\n\n    var riskLabel = cur.isScreenout ? '砂堵高危 ' + cur.screenoutProb.toFixed(0) + '%' : (cur.isBarrierBreach ? '穿层出水' : '低风险 ' + cur.screenoutProb.toFixed(0) + '%');\n    document.getElementById('kpiRisk').innerHTML = cur.UI.toFixed(2) + '<small>' + riskLabel + '</small>';\n    document.getElementById('kpiRiskDelta').textContent =\n      '最高泵压 ' + cur.pMax.toFixed(1) + ' MPa (限85) · ' + (cur.isBarrierBreach ? '已突破底水红线！' : '未穿底水隔层');\n    document.getElementById('kpiRiskCard').className = 'kpi ' + ((cur.isScreenout || cur.isBarrierBreach) ? 'bad' : (cur.UI < 0.72 ? 'warn' : 'ok'));\n\n    // 动态专业解读 (.insight)\n    var insightBox = document.getElementById('insightBox');\n    var insightTag = document.getElementById('insightTag');\n    var insightText = document.getElementById('insightText');\n    var stepInfo = STEP_META[state.step] || STEP_META[3];\n    document.getElementById('stepFocusBadge').textContent = stepInfo.badge;\n\n    if (cur.isScreenout || cur.isBarrierBreach) {\n      insightBox.className = 'insight bad';\n      insightTag.textContent = '风险拦截 · 越界告警';\n      var reason = '';\n      if (cur.dc < 9.5) {\n        reason += '当前簇间距过密（<b>dc=' + cur.dc.toFixed(1) + ' m，段内达 ' + cur.Nc + ' 簇</b>），外侧裂缝张开引发高达 <b>+' + cur.clusters[Math.floor(cur.Nc / 2)].deltaSigmaS.toFixed(1) + ' MPa</b> 的应力阴影挤压，导致中间射孔簇进液占比跌至 <b>' + (cur.clusters[Math.floor(cur.Nc / 2)].fluidShare * 100).toFixed(1) + '%</b>（簇间均匀度仅 <b>' + cur.UI.toFixed(2) + '</b>）；';\n      }\n      if (cur.isScreenout) {\n        reason += '受抑窄缝内支撑剂桥堵叠加孔眼摩阻，使井口最高泵压飙升至 <b>' + cur.pMax.toFixed(1) + ' MPa（突破 85 MPa 安全红线，砂堵概率 ' + cur.screenoutProb.toFixed(0) + '%）</b>。';\n      }\n      if (cur.isBarrierBreach) {\n        reason += '同时外侧簇分流排量过大，最大缝高冲至 <b>' + cur.maxHf.toFixed(1) + ' m（超出隔层遮挡厚度 ' + z.barrierH.toFixed(0) + ' m）</b>，触发纵向穿底水风险！';\n      }\n      insightText.innerHTML = stepInfo.lead + '<br>' + reason + ' 建议点击左侧 <b>「★ 一键贝叶斯寻优」</b> 将簇间距退让至 <b>' + z.opt.dc.toFixed(1) + ' m</b>、排量调至 <b>' + z.opt.Q.toFixed(1) + ' m³/min</b>。';\n    } else if (cur.UI < 0.75 || npvDelta < 5) {\n      insightBox.className = 'insight warn';\n      insightTag.textContent = '寻优诊断 · 存在提升空间';\n      insightText.innerHTML = stepInfo.lead + '<br>当前处于 <b>' + z.name + '</b>，方案虽未触发砂堵或穿层，但距离帕累托最优拐点仍有明显差距：当前簇间距 <b>' + cur.dc.toFixed(1) + ' m</b> 下簇间均匀度为 <b>' + cur.UI.toFixed(2) + '</b>，单段净现值 NPV 为 <b>+' + cur.npv.toFixed(1) + ' 万元</b>（最优可达 <b>+' + paretoData.knee.npv.toFixed(1) + ' 万元</b>）。可点击等高线图上的 <b>★ 星标位置</b> 或一键寻优按钮自动逼近帕累托前沿。';\n    } else {\n      insightBox.className = 'insight';\n      insightTag.textContent = '寻优诊断 · 帕累托高产稳态';\n      insightText.innerHTML = stepInfo.lead + '<br>针对 <b>' + z.name + '</b>（最小主应力 <b>' + z.sigmaH.toFixed(1) + ' MPa</b>），代理模型寻优锁定簇间距 <b>dc=' + cur.dc.toFixed(1) + ' m（' + cur.Nc + ' 簇）</b>、排量 <b>Q=' + cur.Q.toFixed(1) + ' m³/min</b>、加砂强度 <b>' + cur.Mp.toFixed(1) + ' t/m</b>：有效消除了簇间应力阴影抑制（均匀度高达 <b>' + cur.UI.toFixed(2) + '</b>），缝高稳控在 <b>' + cur.maxHf.toFixed(1) + ' m</b> 安全隔层内；相比传统均匀模版，首年累产 EUR 提升 <b>+' + eurDeltaPct.toFixed(1) + '%</b>，单段净现值净增 <b>+' + npvDelta.toFixed(1) + ' 万元</b>。';\n    }\n  }\n\n  /* =========================================================\n     10. 统一重绘与交互事件绑定\n     ========================================================= */\n  var cachedPareto = null;\n  var cachedZone = null;\n\n  function renderAll() {\n    if (cachedZone !== state.zone) {\n      cachedPareto = buildParetoPopulation(state.zone);\n      cachedZone = state.zone;\n    }\n    var cur = evaluateSurrogate(state.zone, state.dc, state.Q, state.Mp, state.Vf);\n    drawFractureCanvas(cur);\n    drawSurfaceCanvas(cur, cachedPareto);\n    drawParetoSvg(cur, cachedPareto);\n    drawClusterSvg(cur);\n    updateKpisAndInsight(cur, cachedPareto);\n  }\n\n  function applyParams(dc, Q, Mp, Vf) {\n    state.dc = Math.max(6, Math.min(24, Math.round(dc * 2) / 2));\n    state.Q = Math.max(8, Math.min(18, Math.round(Q * 5) / 5));\n    state.Mp = Math.max(1.0, Math.min(3.8, Math.round(Mp * 10) / 10));\n    state.Vf = Math.max(12, Math.min(36, Math.round(Vf * 2) / 2));\n    renderAll();\n  }\n\n  function animateToTarget(target) {\n    if (state.animating) return;\n    state.animating = true;\n    var start = { dc: state.dc, Q: state.Q, Mp: state.Mp, Vf: state.Vf };\n    state.searchTrail = [{ dc: start.dc, Q: start.Q }];\n    var steps = 18;\n    var frame = 0;\n\n    function tick() {\n      frame++;\n      var t = frame / steps;\n      var ease = 1 - Math.pow(1 - t, 3);\n      // 加入轻微贝叶斯螺旋探索感\n      var spiral = Math.sin(t * Math.PI * 2) * (1 - ease);\n      state.dc = Math.round((start.dc + (target.dc - start.dc) * ease + spiral * 1.4) * 2) / 2;\n      state.Q = Math.round((start.Q + (target.Q - start.Q) * ease - spiral * 0.8) * 5) / 5;\n      state.Mp = Math.round((start.Mp + (target.Mp - start.Mp) * ease) * 10) / 10;\n      state.Vf = Math.round((start.Vf + (target.Vf - start.Vf) * ease) * 2) / 2;\n      state.searchTrail.push({ dc: state.dc, Q: state.Q });\n      renderAll();\n\n      if (frame < steps) {\n        requestAnimationFrame(tick);\n      } else {\n        state.animating = false;\n        applyParams(target.dc, target.Q, target.Mp, target.Vf);\n      }\n    }\n    requestAnimationFrame(tick);\n  }\n\n  function init() {\n    // 1) 流程步进条点击\n    var stepBtns = document.querySelectorAll('#stepper button');\n    stepBtns.forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var idx = +btn.getAttribute('data-step');\n        state.step = idx;\n        stepBtns.forEach(function (b, i) {\n          b.className = i < idx ? 'done' : (i === idx ? 'on' : '');\n        });\n        renderAll();\n      });\n    });\n\n    // 2) 地质甜点段切换\n    var zoneBtns = document.querySelectorAll('#zoneList .zone-btn');\n    zoneBtns.forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        zoneBtns.forEach(function (b) { b.classList.remove('on'); });\n        btn.classList.add('on');\n        state.zone = btn.getAttribute('data-zone');\n        state.searchTrail = [];\n        var opt = ZONES[state.zone].opt;\n        applyParams(opt.dc, opt.Q, opt.Mp, opt.Vf);\n      });\n    });\n\n    // 3) 四个连续参数滑杆\n    ['slDc', 'slQ', 'slMp', 'slVf'].forEach(function (id) {\n      document.getElementById(id).addEventListener('input', function (e) {\n        var v = parseFloat(e.target.value);\n        if (id === 'slDc') state.dc = v;\n        if (id === 'slQ') state.Q = v;\n        if (id === 'slMp') state.Mp = v;\n        if (id === 'slVf') state.Vf = v;\n        renderAll();\n      });\n    });\n\n    // 4) 一键贝叶斯寻优 & 对比常规均匀方案按钮\n    document.getElementById('btnOptimize').addEventListener('click', function () {\n      state.step = 3;\n      stepBtns.forEach(function (b, i) { b.className = i < 3 ? 'done' : (i === 3 ? 'on' : ''); });\n      animateToTarget(ZONES[state.zone].opt);\n    });\n\n    document.getElementById('btnUniform').addEventListener('click', function () {\n      state.searchTrail = [];\n      var uni = ZONES[state.zone].uni;\n      applyParams(uni.dc, uni.Q, uni.Mp, uni.Vf);\n    });\n\n    // 5) 复选框开关\n    document.getElementById('chkShadow').addEventListener('change', function (e) {\n      state.showShadow = e.target.checked;\n      renderAll();\n    });\n    document.getElementById('chkRisk').addEventListener('change', function (e) {\n      state.showRisk = e.target.checked;\n      renderAll();\n    });\n\n    // 6) 响应曲面指标切换分段按钮\n    var metricBtns = document.querySelectorAll('#surfMetricSeg button');\n    metricBtns.forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        metricBtns.forEach(function (b) { b.classList.remove('on'); });\n        btn.classList.add('on');\n        state.surfMetric = btn.getAttribute('data-metric');\n        renderAll();\n      });\n    });\n\n    // 7) 主视图 1（裂缝剖面）悬停浮动提示\n    var fracCanvas = document.getElementById('fracCanvas');\n    var fracTip = document.getElementById('fracTip');\n    fracCanvas.addEventListener('mousemove', function (e) {\n      var rect = fracCanvas.getBoundingClientRect();\n      var mx = (e.clientX - rect.left) * (840 / rect.width);\n      var my = (e.clientY - rect.top) * (296 / rect.height);\n      var hit = -1;\n      for (var i = 0; i < clusterHitBoxes.length; i++) {\n        var b = clusterHitBoxes[i];\n        if (mx >= b.x0 && mx <= b.x1 && my >= b.y0 && my <= b.y1) {\n          hit = b.idx;\n          break;\n        }\n      }\n      if (hit !== state.hoverCluster) {\n        state.hoverCluster = hit;\n        renderAll();\n      }\n      if (hit >= 0) {\n        var cur = evaluateSurrogate(state.zone, state.dc, state.Q, state.Mp, state.Vf);\n        var cl = cur.clusters[hit];\n        fracTip.innerHTML =\n          '<b>第 #' + cl.index + ' 射孔簇</b> (' + (cl.stunted ? '应力阴影受抑' : '有效开启') + ')<br>' +\n          '半缝长 xf: <b>' + cl.xf.toFixed(1) + ' m</b> · 缝高 hf: <b>' + cl.hf.toFixed(1) + ' m</b><br>' +\n          '分流液量: <b>' + (cl.fluidShare * 100).toFixed(1) + '%</b> · 进砂占比: <b>' + (cl.propShare * 100).toFixed(1) + '%</b><br>' +\n          '附加挤压应力 Δσs: <b>+' + cl.deltaSigmaS.toFixed(1) + ' MPa</b>';\n        fracTip.style.left = Math.min(rect.width - 110, Math.max(110, e.clientX - rect.left)) + 'px';\n        fracTip.style.top = Math.max(68, e.clientY - rect.top) + 'px';\n        fracTip.classList.add('on');\n      } else {\n        fracTip.classList.remove('on');\n      }\n    });\n    fracCanvas.addEventListener('mouseleave', function () {\n      state.hoverCluster = -1;\n      fracTip.classList.remove('on');\n      renderAll();\n    });\n\n    // 8) 主视图 2（2D 代理响应曲面）悬停提示与点击/拖拽直接选点\n    var surfCanvas = document.getElementById('surfCanvas');\n    var surfTip = document.getElementById('surfTip');\n    var isDraggingSurf = false;\n\n    function pickFromSurfEvent(e, updateState) {\n      var rect = surfCanvas.getBoundingClientRect();\n      var mx = (e.clientX - rect.left) * (840 / rect.width);\n      var my = (e.clientY - rect.top) * (288 / rect.height);\n      var bx = surfPlotBox.x0, by = surfPlotBox.y0, bw = surfPlotBox.w, bh = surfPlotBox.h;\n      if (mx < bx || mx > bx + bw || my < by || my > by + bh) {\n        surfTip.classList.remove('on');\n        return;\n      }\n      var dc = 6.0 + ((mx - bx) / bw) * 18.0;\n      var Q = 18.0 - ((my - by) / bh) * 10.0;\n      dc = Math.max(6, Math.min(24, Math.round(dc * 2) / 2));\n      Q = Math.max(8, Math.min(18, Math.round(Q * 5) / 5));\n\n      var sim = evaluateSurrogate(state.zone, dc, Q, state.Mp, state.Vf);\n      surfTip.innerHTML =\n        '<b>代理模型实时推断 (dc=' + dc.toFixed(1) + 'm, Q=' + Q.toFixed(1) + ')</b><br>' +\n        '净现值 NPV: <b>+' + sim.npv.toFixed(1) + ' 万元</b> · EUR: <b>' + sim.eur.toFixed(1) + ' 万m³</b><br>' +\n        '簇均匀度 UI: <b>' + sim.UI.toFixed(2) + '</b> · 最高泵压: <b>' + sim.pMax.toFixed(1) + ' MPa</b>';\n      surfTip.style.left = Math.min(rect.width - 120, Math.max(120, e.clientX - rect.left)) + 'px';\n      surfTip.style.top = Math.max(64, e.clientY - rect.top) + 'px';\n      surfTip.classList.add('on');\n\n      if (updateState) {\n        state.searchTrail = [];\n        applyParams(dc, Q, state.Mp, state.Vf);\n      }\n    }\n\n    surfCanvas.addEventListener('mousedown', function (e) {\n      isDraggingSurf = true;\n      pickFromSurfEvent(e, true);\n    });\n    window.addEventListener('mouseup', function () {\n      isDraggingSurf = false;\n    });\n    surfCanvas.addEventListener('mousemove', function (e) {\n      pickFromSurfEvent(e, isDraggingSurf);\n    });\n    surfCanvas.addEventListener('mouseleave', function () {\n      surfTip.classList.remove('on');\n    });\n\n    renderAll();\n  }\n\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', init);\n  } else {\n    init();\n  }\n})();\n","enc":"text","size":65145}]};